        #region CP 01.1 User Management
        [HttpGet]
        public ActionResult UserManagementAuthorityInfoDesk()
        {
            ClsMethod_View_CP_UserManagerAuthority sdb = new ClsMethod_View_CP_UserManagerAuthority();
            ClsPrp_ControlPanel_View_UserManagerAuthority aa = new ClsPrp_ControlPanel_View_UserManagerAuthority();
            
            string prmUserRole = string.Empty;
            Int32 prmRequestID = 0;
            prmUserRole = getUserRole();
            aa.prpongoing = sdb.Display_CP_UserManagerAuthority_ByIDandUserRole(prmRequestID, prmUserRole);            

            foreach (var item in aa.prpongoing)
            {               
                aa.UserManagerAuthority_IndexID = item.UserManagerAuthority_IndexID;
                aa.UserManagerAuthority_ID = item.UserManagerAuthority_ID;
                aa.rolesId = item.rolesId;
                aa.rolesName = item.rolesName;
                aa.usersId = item.usersId;
                aa.usersEmail = RegexRemoveEmailCheck(item.usersEmail);
                aa.usersEmailConfirmed = item.usersEmailConfirmed;
                aa.usersPhoneNumber = item.usersPhoneNumber;
                aa.usersPhoneNumberConfirmed = item.usersPhoneNumberConfirmed;
                aa.usersTwoFactorEnabled = item.usersTwoFactorEnabled;
                aa.usersLockoutEndDateUtc = item.usersLockoutEndDateUtc;
                aa.usersLockoutEnabled = item.usersLockoutEnabled;
                aa.usersAccessFailedCount = item.usersAccessFailedCount;
                aa.usersUserName = item.usersUserName;
                aa.userrolesUserId = item.userrolesUserId;
                aa.userrolesRoleId = item.userrolesRoleId;
                aa.A_column = item.A_column;
                aa.B_column = item.B_column;                
            }
            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            aa.RoleAccessFlag = roletypeFlag;
            Session["modelUserManagementAuthorityMIS"] = aa.prpongoing;

            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep(); 
            return View("UserManagementAuthorityInfoDesk", aa);
        }

        //LockoutEnabled Handler (Authority User By ID)
        public JsonResult LockoutEnabledHandler_UserManagementAuthorityById(string prmuserId, string prmuserNam, string prmroleId, string prmLockoutEnabled)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                string userCode = string.Empty;
                string userNamCode = string.Empty;
                string roleCode = string.Empty;

                string lockendCode = "1"; //Yes(1) Lock
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmuserId != string.Empty)
                {
                    userCode = prmuserId;
                }
                if (prmuserNam != string.Empty)
                {
                    userNamCode = prmuserNam;
                }
                if (prmroleId != string.Empty)
                {
                    roleCode = prmroleId;
                }
                if (prmLockoutEnabled != string.Empty)
                {
                    if (prmLockoutEnabled == "true")
                    {
                        // has class YPV(1), request for UnLock. hence set NPV(0)
                        lockendCode = Convert.ToString("0");
                    }
                    else if (prmLockoutEnabled == "false")
                    {
                        // has class NPV(0), request for Lock. hence set YPV(1)
                        lockendCode = Convert.ToString("1");
                    }
                    else
                    {
                        // has class unknown, request for Lock. hence set YPV(1)
                        lockendCode = Convert.ToString("1");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Lock-UnLock authority user details";
                switch (lockendCode)
                {
                    case "0": //NPV
                        RelatedPVMsg = "UnLock request";
                        break;
                    case "1": //YPV
                        RelatedPVMsg = "Lock request";
                        break;
                    default:
                        RelatedPVMsg = "others (LockUnlock)";
                        break;
                }
                #endregion
                ClsMethod_View_CP_UserManagerAuthority sdb = new ClsMethod_View_CP_UserManagerAuthority();
                retvalueLockUnlock = sdb.Update_LockUnlockHandler_CP_UserManagerAuthorityByIndex(userCode, userNamCode, roleCode, lockendCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "User locked successfully of the authority.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "User UnLocked successfully of the authority.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

        //Email Confirm Handler (Authority User By ID)
        public JsonResult EmailConfirmEnabledHandler_UserManagementAuthorityById(string prmuserId, string prmuserNam, string prmroleId, string prmEmailConfirm)
        {
            Int32 retvalueEmailConfirm = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                string userCode = string.Empty;
                string userNamCode = string.Empty;
                string roleCode = string.Empty;

                string EmailConfirmCode = "1"; //Yes(1) Lock
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmuserId != string.Empty)
                {
                    userCode = prmuserId;
                }
                if (prmuserNam != string.Empty)
                {
                    userNamCode = prmuserNam;
                }
                if (prmroleId != string.Empty)
                {
                    roleCode = prmroleId;
                }
                if (prmEmailConfirm != string.Empty)
                {
                    if (prmEmailConfirm == "true")
                    {
                        // has class YPV(1), request for UnLock. hence set NPV(0)
                        EmailConfirmCode = Convert.ToString("0");
                    }
                    else if (prmEmailConfirm == "false")
                    {
                        // has class NPV(0), request for Lock. hence set YPV(1)
                        EmailConfirmCode = Convert.ToString("1");
                    }
                    else
                    {
                        // has class unknown, request for Lock. hence set YPV(1)
                        EmailConfirmCode = Convert.ToString("1");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Email confirmation of the authority user details";
                switch (EmailConfirmCode)
                {
                    case "0": //NPV
                        RelatedPVMsg = "Email disconfirm request";
                        break;
                    case "1": //YPV
                        RelatedPVMsg = "Email confirm request";
                        break;
                    default:
                        RelatedPVMsg = "others (Email Confirm)";
                        break;
                }
                #endregion
                ClsMethod_View_CP_UserManagerAuthority sdb = new ClsMethod_View_CP_UserManagerAuthority();
                retvalueEmailConfirm = sdb.Update_EmailConfirmEnabledHandler_CP_UserManagerAuthorityByIndex(userCode, userNamCode, roleCode, EmailConfirmCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvalueEmailConfirm; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Email confirmed successfully of the authority.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Email disconfirm successfully of the authority.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

        public void ExportUserManagementAuthorityToExcel()
        {
            var objXlslist = Session["modelUserManagementAuthorityMIS"] as List<ClsPrp_ControlPanel_View_UserManagerAuthority>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");
            workSheet.TabColor = System.Drawing.Color.Black;
            workSheet.DefaultRowHeight = 12;
            //Header of table  
            //  
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "User Name";
            workSheet.Cells[1, 3].Value = "Role Description";
            workSheet.Cells[1, 4].Value = "Email Address";
            workSheet.Cells[1, 5].Value = "Phone Number";
            workSheet.Cells[1, 6].Value = "Email Confirmed Status";
            workSheet.Cells[1, 7].Value = "Phone Number Confirmed Status";
            workSheet.Cells[1, 8].Value = "Two-Factor Authentification";
            workSheet.Cells[1, 9].Value = "Locked Status";
            workSheet.Cells[1, 10].Value = "Locked till Date";
            workSheet.Cells[1, 11].Value = "Remarks, If Any";
            //Body of table  
            //  
            int recordIndex = 2;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.usersUserName;
                workSheet.Cells[recordIndex, 3].Value = QRcodeItem.rolesName;
                workSheet.Cells[recordIndex, 4].Value = QRcodeItem.usersEmail;
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.usersPhoneNumber;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.usersEmailConfirmed == 1 ? "Yes" : "No";
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.usersPhoneNumberConfirmed == 1 ? "Yes" : "No";
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.usersTwoFactorEnabled == 1 ? "Yes" : "No";
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.usersLockoutEnabled == 1 ? "Locked" : "Unlocked";
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.usersLockoutEndDateUtc.HasValue ? QRcodeItem.usersLockoutEndDateUtc.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 11].Value = string.Empty;                
                workSheet.Row(recordIndex).Height = 20;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();           

            workSheet.Cells["A1:K1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:K1"].Style.Fill.BackgroundColor.SetColor(Color.Yellow);

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 11])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofAuthorityUsers_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }
