        [HttpPost]
        public ActionResult UserManagementListInfoDesk(ClsPrp_ControlPanel_View_UserManagerList smodel)
        {
            ClsMethod_View_CP_UserManagerList sdb = new ClsMethod_View_CP_UserManagerList();
            ClsPrp_ControlPanel_View_UserManagerList aa = new ClsPrp_ControlPanel_View_UserManagerList();
            Clsprp_MIS_ProjectAverageFileTimeExportExcel aaXls = new Clsprp_MIS_ProjectAverageFileTimeExportExcel();

            Int32 varChkOptionType = 0;
            varChkOptionType = smodel.IsApplicationDateFlag;
            //Input Parm
            if (varChkOptionType == 21)//21:E and 22:U
            {
                ModelState.Remove("InputEntry_UserName");
            }
            else
            {
                ModelState.Remove("InputEntry_EmailAddress");
            }
            //Property User
            ModelState.Remove("rolesName");
            ModelState.Remove("usersEmail");
            ModelState.Remove("usersEmailConfirmed");
            ModelState.Remove("usersPhoneNumber");
            ModelState.Remove("usersPhoneNumberConfirmed");
            ModelState.Remove("usersTwoFactorEnabled");
            ModelState.Remove("usersLockoutEndDateUtc");
            ModelState.Remove("usersLockoutEnabled");
            ModelState.Remove("usersUserName");
            if (ModelState.IsValid)
            {
                string UserID_Role = string.Empty;
                Int32 flagApplicationForMode = 0;
                Int32 flagApplicationOption = 0;
                string InputEmailID = string.Empty;
                string InputUserName = string.Empty;

                flagApplicationForMode = smodel.IsApplicationModeFlag;//51:P/A/C
                flagApplicationOption = smodel.IsApplicationDateFlag;//21:E/U

                InputEmailID = smodel.InputEntry_EmailAddress;
                InputUserName = smodel.InputEntry_UserName;

                aa.prpongoing = sdb.Display_CP_UserManager_ByIDandUserRoleByFilter(UserID_Role, flagApplicationForMode, flagApplicationOption, InputEmailID, InputUserName).ToList();

                foreach (var item in aa.prpongoing)
                {
                    aa.UserManagerAuthority_IndexID = item.UserManagerAuthority_IndexID;
                    aa.UserManagerAuthority_ID = item.UserManagerAuthority_ID;
                    aa.rolesId = item.rolesId;
                    aa.rolesName = item.rolesName;
                    aa.usersId = item.usersId;
                    aa.usersEmail = RegexRemoveEmailCheck(item.usersEmail);
                    aa.usersEmailConfirmed = item.usersEmailConfirmed;
                    aa.usersPhoneNumber = item.usersPhoneNumber;
                    aa.usersPhoneNumberConfirmed = item.usersPhoneNumberConfirmed;
                    aa.usersTwoFactorEnabled = item.usersTwoFactorEnabled;
                    aa.usersLockoutEndDateUtc = item.usersLockoutEndDateUtc;
                    aa.usersLockoutEnabled = item.usersLockoutEnabled;
                    aa.usersAccessFailedCount = item.usersAccessFailedCount;
                    aa.usersUserName = item.usersUserName;
                    aa.userrolesUserId = item.userrolesUserId;
                    aa.userrolesRoleId = item.userrolesRoleId;
                    aa.A_column = item.A_column;
                    aa.B_column = item.B_column;
                }

            }
            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            aa.RoleAccessFlag = roletypeFlag;
            Session["modelUserManagementListMIS"] = aa.prpongoing;

            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();
            return View("UserManagementListInfoDesk", aa);
        }

