        private string GetDefaultPasswordStringValue(string emailaddress, string roledescription)
        {
            string result = string.Empty;
            string rname = string.Empty;
            string emname = string.Empty;
            string ptname = string.Empty;
            //First STR
            if (emailaddress.Length >= 5)
            {
                emname = emailaddress.Substring(0, 5);
            }
            else
            {
                emname = "PRERA";
            }
            //Second STR
            switch (roledescription)
            {
                case "Promoter":
                    rname = "Pbpromoter";
                    break;
                case "RealEstateAgent":
                    rname = "Pbagent";
                    break;
                case "Complainant":
                    rname = "Pbcomplaint";
                    break;
                default:
                    break;
            }
            //Third STR
            ptname = "@1";
            //Set Value
            result = string.Concat(string.Concat(emname, rname), ptname);
            return result;
        }       
        
        //Reset Password Handler (Log History)
        public bool ResetPasswordHandler_UserManagementLogHistoryById(ClsPrp_ControlPanel_View_UserManagerPassword prmObject, string RequestCode)
        {
            Int32 retvalueLogHistory = 0;
            Int32 retValue = 1;
            bool retBoolean = false;
            try
            {
                #region Parameters
                string userID = string.Empty;                
                string userName = string.Empty;
                string roleID = string.Empty;
                string roleName = string.Empty;
                string userEmail = string.Empty;

                string preparedByUserName = string.Empty;
                string preparedByUserID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                userID = prmObject.usersId;
                userName = prmObject.usersUserName;
                roleID = prmObject.rolesId;
                roleName = prmObject.rolesName;
                userEmail = prmObject.usersEmail;

                preparedByUserID = User.Identity.GetUserId();
                preparedByUserName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Reset password user details by Admin";

                switch (RequestCode)
                {
                    case "CPWD":
                        RelatedPVMsg = "Reset request for Change Password";
                        break;
                    case "SPWD":
                        RelatedPVMsg = "Reset request for Set Password";
                        break;
                    case "SDPWD":
                        RelatedPVMsg = "Reset request for Set Default Password";
                        break;
                    default:
                        RelatedPVMsg = "others (Reset Password)";
                        break;
                }
                #endregion
                ClsMethod_View_CP_UserManagerList sdb = new ClsMethod_View_CP_UserManagerList();
                retvalueLogHistory = sdb.AddLogHistory_ResetPasswordHandler_CP_UserManagerListByIndex(userID, roleName, userName, roleID, userEmail, preparedByUserName, preparedByUserID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            if (retValue == 1)
            {
                if (retvalueLogHistory == 1)
                {
                    retBoolean = true;
                }
            }
            return retBoolean;
        }

        public void ExportUserManagementWebPortalResetPwdToExcel()
        {
            var objXlslist = Session["modelUserManagementPasswordListMIS"] as List<ClsPrp_ControlPanel_View_UserManagerList>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");
            workSheet.TabColor = System.Drawing.Color.Black;
            workSheet.DefaultRowHeight = 12;
            //Header of table  
            //  
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "User Name";
            workSheet.Cells[1, 3].Value = "Role Description";
            workSheet.Cells[1, 4].Value = "Email Address";
            workSheet.Cells[1, 5].Value = "Phone Number";
            workSheet.Cells[1, 6].Value = "Email Confirmed Status";
            workSheet.Cells[1, 7].Value = "Phone Number Confirmed Status";
            workSheet.Cells[1, 8].Value = "Two-Factor Authentification";
            workSheet.Cells[1, 9].Value = "Locked Status";
            workSheet.Cells[1, 10].Value = "Locked till Date";
            workSheet.Cells[1, 11].Value = "Remarks, If Any";
            //Body of table  
            //  
            int recordIndex = 2;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.usersUserName;
                workSheet.Cells[recordIndex, 3].Value = QRcodeItem.rolesName;
                workSheet.Cells[recordIndex, 4].Value = QRcodeItem.usersEmail;
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.usersPhoneNumber;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.usersEmailConfirmed == 1 ? "Yes" : "No";
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.usersPhoneNumberConfirmed == 1 ? "Yes" : "No";
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.usersTwoFactorEnabled == 1 ? "Yes" : "No";
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.usersLockoutEnabled == 1 ? "Locked" : "Unlocked";
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.usersLockoutEndDateUtc.HasValue ? QRcodeItem.usersLockoutEndDateUtc.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 11].Value = string.Empty;
                workSheet.Row(recordIndex).Height = 20;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();

            workSheet.Cells["A1:K1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:K1"].Style.Fill.BackgroundColor.SetColor(Color.Yellow);

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 11])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofWebPortalResetUsers_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }

