        //LockoutEnabled Handler (WebPortal User By ID)
        public JsonResult LockoutEnabledHandler_UserManagementWebPortalListById(string prmuserId, string prmuserNam, string prmroleId, string prmLockoutEnabled)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                string userCode = string.Empty;
                string userNamCode = string.Empty;
                string roleCode = string.Empty;

                string lockendCode = "1"; //Yes(1) Lock
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmuserId != string.Empty)
                {
                    userCode = prmuserId;
                }
                if (prmuserNam != string.Empty)
                {
                    userNamCode = prmuserNam;
                }
                if (prmroleId != string.Empty)
                {
                    roleCode = prmroleId;
                }
                if (prmLockoutEnabled != string.Empty)
                {
                    if (prmLockoutEnabled == "true")
                    {
                        // has class YPV(1), request for UnLock. hence set NPV(0)
                        lockendCode = Convert.ToString("0");
                    }
                    else if (prmLockoutEnabled == "false")
                    {
                        // has class NPV(0), request for Lock. hence set YPV(1)
                        lockendCode = Convert.ToString("1");
                    }
                    else
                    {
                        // has class unknown, request for Lock. hence set YPV(1)
                        lockendCode = Convert.ToString("1");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Lock-UnLock web-portal user details";
                switch (lockendCode)
                {
                    case "0": //NPV
                        RelatedPVMsg = "UnLock request";
                        break;
                    case "1": //YPV
                        RelatedPVMsg = "Lock request";
                        break;
                    default:
                        RelatedPVMsg = "others (LockUnlock)";
                        break;
                }
                #endregion
                ClsMethod_View_CP_UserManagerList sdb = new ClsMethod_View_CP_UserManagerList();
                retvalueLockUnlock = sdb.Update_LockUnlockHandler_CP_UserManagerListByIndex(userCode, userNamCode, roleCode, lockendCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "User locked successfully of the web-portal.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "User UnLocked successfully of the web-portal.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

