        [HttpPost]
        [ValidateAntiForgeryToken]
        public async Task<ActionResult> UserManagementRegisterAuthorityDetails(ClsPrp_ControlPanel_View_UserManagerRegistration smodel)
        {
            ClsMethod_View_CP_UserManagerList sdb = new ClsMethod_View_CP_UserManagerList();
            ClsPrp_ControlPanel_View_UserManagerRegistration aa = new ClsPrp_ControlPanel_View_UserManagerRegistration();

            string retStr = "NA";
            //When Capcha is Valid
            if (this.IsCaptchaValid("Captcha is not valid"))
            {                
                Int32 varChkOptionType = 0;
                string varUserRoles = string.Empty;
                varChkOptionType = smodel.IsApplicationModeFlag;
                //Property User Input
                if (varChkOptionType == 31)//31:WP-U and 32:Auth-U
                {
                    ModelState.Remove("Input_EmployeeProfileID");
                    ModelState.Remove("Input_EmployeeName");
                }
                else if(varChkOptionType == 32)
                {
                    ModelState.Remove("rolesName");
                }
                ModelState.Remove("usersEmailConfirmed");
                ModelState.Remove("usersPhoneNumber");
                ModelState.Remove("usersPhoneNumberConfirmed");
                ModelState.Remove("usersTwoFactorEnabled");
                ModelState.Remove("usersLockoutEndDateUtc");
                ModelState.Remove("usersLockoutEnabled");
                ModelState.Remove("usersUserName");
                if (ModelState.IsValid)
                {
                    var user = new ApplicationUser { UserName = smodel.Input_UserName, Email = smodel.usersEmail, };
                    var result = await UserManager.CreateAsync(user, smodel.Input_Password);
                    if (result.Succeeded)
                    {
                        if (varChkOptionType == 31)//31:WP-U and 32:Auth-U
                        {
                            varUserRoles = smodel.rolesName;
                        }
                        else if(varChkOptionType == 32)
                        {
                            varUserRoles = smodel.userrolesRoleId;
                        }
                        //Assign Role to user Here   
                        await this.UserManager.AddToRoleAsync(user.Id, varUserRoles);
                        //Assign UserID and Employee Name
                        if (varChkOptionType == 32)//32:Auth-U
                        {
                            string UID = User.Identity.GetUserId();
                            string UserNam = User.Identity.Name;
                            smodel.usersId = user.Id;
                            bool retValue = sdb.Update_UserProfileMasterDetails_ByUserID(smodel, UID, UserNam);
                        }

                        retStr = "Success! User ID: " + user.UserName.ToString();
                        TempData["returnSubmitMessageFlag"] = "FlagYES"; TempData.Keep();
                    }
                    else
                    {
                        //Failed
                        retStr = "Bad Request! Failed.";
                        TempData["returnSubmitMessageFlag"] = "FlagNO"; TempData.Keep();
                    }                    
                }
                else
                {
                    retStr = "Error! Invalid Inputs.";
                    TempData["returnSubmitMessageFlag"] = "FlagNO"; TempData.Keep();
                }
            }
            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            aa.RoleAccessFlag = roletypeFlag;

            TempData["returnSubmitMessage"] = retStr; TempData.Keep();            
            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();
            return View("UserManagementRegisterAuthorityDetails", aa);
        }

