        [HttpPost]
        public ActionResult QuarterlyUpdateApplyStatusDetails(ClsPrp_ControlPanel_View_QuarterlyUpdatesApplyFile smodel)
        {
            ClsMethod_View_CP_QuarterlyUpdatesManagerList sdb = new ClsMethod_View_CP_QuarterlyUpdatesManagerList();
            ClsPrp_ControlPanel_View_QuarterlyUpdatesApplyFile aa = new ClsPrp_ControlPanel_View_QuarterlyUpdatesApplyFile();
            ClsPrp_ControlPanel_View_QuarterlyUpdatesProjectFile rtnobj = new ClsPrp_ControlPanel_View_QuarterlyUpdatesProjectFile();

            string error = string.Empty;
            string UserRole = getUserRole();
            string UID = User.Identity.GetUserId();
            string UserNam = User.Identity.Name;

            try
            {
                ModelState.Remove("QUpdateProject_Year");
                ModelState.Remove("QUpdateProject_QuarterName");

                if (ModelState.IsValid)
                {
                    aa.QUpdateProject_Year = DateTime.Now.Year;
                    aa.QUpdateProject_QuarterName = "NA";

                    var numbers = sdb.Add_QuarterlyUpdateStatusDetails(smodel, UserNam, UID);
                    if (numbers.Item1)
                    {
                        string pNumberValue = numbers.Item2.ToString();
                        TempData["MessageQUPsApplyStatus"] = "Successfully Submitted (" + pNumberValue + ")"; TempData.Keep();
                        TempData["QUPsApplysubmitvalue"] = "Save"; TempData.Keep();
                        ModelState.Clear();
                    }                    
                }
            }
            catch (Exception ex)
            {
                error = ex.Message;
            }

            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            rtnobj.RoleAccessFlag = roletypeFlag;

            Session["modelProjectQUPstatusaccessMIS"] = rtnobj.prpongoing;

            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();
            return View("QuarterlyUpdateManagementRegAccessStatusDetails", rtnobj);
        }
