        //Locked-Enabled Handler (WebPortal User By ID)
        public JsonResult LockedEnabledHandler_ProjectEditManagementListById(string pmindexId, string pmnameId, string pmpromoterId, string pmprojectId, string pmrefId, string pmLockoutEnabled)
        {
            Int32 retvalueLockUnlock = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                string indexCode = string.Empty;
                string idCode = string.Empty;
                string promoterCode = string.Empty;
                string projectCode = string.Empty;
                string referenceCode = string.Empty;

                string lockendCode = "1"; //Yes(1) Lock
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (pmindexId != string.Empty)
                {
                    indexCode = pmindexId;
                }
                if (pmnameId != string.Empty)
                {
                    idCode = pmnameId;
                }
                if (pmpromoterId != string.Empty)
                {
                    promoterCode = pmpromoterId;
                }
                if (pmprojectId != string.Empty)
                {
                    projectCode = pmprojectId;
                }
                if (pmrefId != string.Empty)
                {
                    referenceCode = pmrefId;
                }
                if (pmLockoutEnabled != string.Empty)
                {
                    if (pmLockoutEnabled == "true")
                    {
                        // has class YPV(1), request for UnLock. hence set NPV(0)
                        lockendCode = Convert.ToString("0");
                    }
                    else if (pmLockoutEnabled == "false")
                    {
                        // has class NPV(0), request for Lock. hence set YPV(1)
                        lockendCode = Convert.ToString("1");
                    }
                    else
                    {
                        // has class unknown, request for Lock. hence set YPV(1)
                        lockendCode = Convert.ToString("1");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Lock-UnLock web-portal project detail options";
                switch (lockendCode)
                {
                    case "0": //NPV
                        RelatedPVMsg = "UnLock request";
                        break;
                    case "1": //YPV
                        RelatedPVMsg = "Lock request";
                        break;
                    default:
                        RelatedPVMsg = "others (LockUnlock)";
                        break;
                }
                #endregion
                ClsMethod_View_CP_ProjectLockUnlockManagerList sdb = new ClsMethod_View_CP_ProjectLockUnlockManagerList();
                retvalueLockUnlock = sdb.Update_LockUnlockHandler_CP_ProjectLockUnlockManagerListByIndex(indexCode, idCode, promoterCode, projectCode, referenceCode, lockendCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvalueLockUnlock; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Enabled lock/unlock successfully of the registered projects.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Disabled lock/unlock successfully of the registered projects.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }

