        [HttpPost]
        public ActionResult ProjectEditApplySuperLockUnlockStatusDetails(ClsPrp_ControlPanel_View_ProjectSuperLockUnlockApplyConfirm smodel, string submit)
        {
            ClsMethod_View_CP_ProjectLockUnlockManagerList sdb = new ClsMethod_View_CP_ProjectLockUnlockManagerList();
            ClsPrp_ControlPanel_View_ProjectSuperLockUnlockApplyConfirm aa = new ClsPrp_ControlPanel_View_ProjectSuperLockUnlockApplyConfirm();
            ClsPrp_ControlPanel_View_ProjectSuperLockUnlockList rtnobj = new ClsPrp_ControlPanel_View_ProjectSuperLockUnlockList();

            string error = string.Empty;
            string UserRole = getUserRole();
            string UID = User.Identity.GetUserId();
            string UserNam = User.Identity.Name;

            Int64 prmPromoterID = 0;
            Int64 prmProjectID = 0;
            string prmDiaryNumber = string.Empty;

            try
            {
                ModelState.Remove("Project_Name");
                ModelState.Remove("Promoter_Name");
                ModelState.Remove("RERAnumberRegistration");
                ModelState.Remove("RERAnumberIssueDate");
                ModelState.Remove("RERAnumberRegUptoDate");
                if (ModelState.IsValid)
                {
                    prmPromoterID = smodel.Related_Promoter_ID;
                    prmProjectID = smodel.Related_Project_ID;
                    prmDiaryNumber = smodel.ProjectRegDiaryNumber_Name;

                    #region Add or Update
                    if (smodel.IsLockedEnable == 1 && smodel.IsLockedConfirmed == 1)
                    {
                        switch (submit)
                        {
                            case "Confirm Promoter Detail":
                                var numbersCPD = sdb.Add_Project_PromoterProfileDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersCPD.Item1)
                                {
                                    string pNumberValue = numbersCPD.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }                               
                                break;
                            case "Confirm Co-Promoter Detail":
                                var numbersCCPD = sdb.Add_Project_CoPromoterDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersCCPD.Item1)
                                {
                                    string pNumberValue = numbersCCPD.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }                                
                                break;
                            case "Confirm Project Detail":
                                var numbersCPRJD = sdb.Add_Project_ProjectDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersCPRJD.Item1)
                                {
                                    string pNumberValue = numbersCPRJD.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }                                
                                break;
                            case "Confirm Quarterly Updates Detail":
                                var numbersCQUD = sdb.Add_Project_QuarterlyUpdatesDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersCQUD.Item1)
                                {
                                    string pNumberValue = numbersCQUD.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }                                
                                break;
                            case "Confirm Year Mapping":
                                var numbersYM = sdb.Add_Project_QuarterlyUpdate_YearMappingDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersYM.Item1)
                                {
                                    string pNumberValue = numbersYM.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();                                    
                                }
                                break;
                            case "Confirm Promoter Lock":
                                var numbersPML = sdb.Add_Project_Registration_PromoterLockDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersPML.Item1)
                                {
                                    string pNumberValue = numbersPML.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }
                                break;
                            case "Confirm Project Lock":
                                var numbersPL = sdb.Add_Project_Registration_ProjectLockDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersPL.Item1)
                                {
                                    string pNumberValue = numbersPL.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }
                                break;
                            case "Confirm Quarterly Update Lock":
                                var numbersQUL = sdb.Add_Project_Registration_QuarterlyUpdatesLockDetails(smodel, prmProjectID, prmPromoterID, prmDiaryNumber, UserNam, UID);
                                if (numbersQUL.Item1)
                                {
                                    string pNumberValue = numbersQUL.Item2.ToString();
                                    TempData["MessageProjectEditApplyStatus"] = "Successfully Submitted! (" + pNumberValue + ")";
                                    TempData.Keep();
                                }
                                break;
                        }
                    }
                    #endregion
                    ModelState.Clear();      
                }
            }
            catch (Exception ex)
            {
                error = ex.Message;
            }

            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            rtnobj.RoleAccessFlag = roletypeFlag;

            Session["modelProjectProjectEditstatusaccessLockUnlockMIS"] = rtnobj.prpongoing;

            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();
            return View("ProjectEditManagementRegAccessSuperLockUnlockStatusDetails", rtnobj);
