        public void ExportProjectFileReArrangementDocsToExcel()
        {
            var objXlslist = Session["modelProjectFileReArrangementMIS"] as List<ClsPrp_ControlPanel_View_FileRearrangementProjectDocumentDetails>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");            
            workSheet.TabColor = System.Drawing.ColorTranslator.FromHtml("#7bb73f");
            workSheet.DefaultRowHeight = 12;
            //Header of table  
            //  
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "Diary Number";
            workSheet.Cells[1, 3].Value = "Registration Number";
            workSheet.Cells[1, 4].Value = "Project Name";
            workSheet.Cells[1, 5].Value = "Address District Name";
            workSheet.Cells[1, 6].Value = "Document Name";
            workSheet.Cells[1, 7].Value = "Reference Number";
            workSheet.Cells[1, 8].Value = "Date of Reference/Upload";
            workSheet.Cells[1, 9].Value = "Remarks, If Any";
            //Body of table  
            //  
            int recordIndex = 2;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.Project_DiaryNumber;
                workSheet.Cells[recordIndex, 3].Value = QRcodeItem.RERA_RegistrationNumber;
                workSheet.Cells[recordIndex, 4].Value = QRcodeItem.ProjectName;
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.ProjectAddressDistrict;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.ProjectDoc_InfoName;
                workSheet.Cells[recordIndex, 7].Value = QRcodeItem.ProjectDoc_ReferenceNumber;                
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.ProjectDoc_IssueDate.HasValue ? QRcodeItem.ProjectDoc_IssueDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.Remarks_IfAny;
                workSheet.Row(recordIndex).Height = 20;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();

            workSheet.Cells["A1:I1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:I1"].Style.Fill.BackgroundColor.SetColor(ColorTranslator.FromHtml("#7bb73f"));

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 9])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofProjectReArrangementDocuments_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }

