        [HttpPost]
        public ActionResult UpdateOptionsSetRearrangementProjectDocsDetail(ClsPrp_ControlPanel_View_FileRearrangementProjectDocumentDetails[] requestobj)
        {
            ClsMethod_View_CP_FileRearrangementProjectDocuments sdb = new ClsMethod_View_CP_FileRearrangementProjectDocuments();
            ClsPrp_ControlPanel_View_FileRearrangementProjectDocumentDetails objprp = new ClsPrp_ControlPanel_View_FileRearrangementProjectDocumentDetails();

            bool status = false;
            Int64? chkappid = null;
            string retMessage = string.Empty;
            string remarkMessage = string.Empty;

            string io_error = string.Empty;
            string io_UserRole = getUserRole();
            string io_UID = User.Identity.GetUserId();
            string io_UserNam = User.Identity.Name;

            if (requestobj != null)
            {
                foreach (var item in requestobj)
                {                   
                    objprp.ProjectDoc_IndexID = Convert.ToInt64(item.ProjectDoc_IndexID);
                    objprp.ProjectDoc_ID = Convert.ToInt64(item.ProjectDoc_ID);
                    objprp.Promoter_ID = Convert.ToInt64(item.Promoter_ID);
                    objprp.Project_ID = Convert.ToInt64(item.Project_ID);
                    objprp.Project_DiaryNumber = Convert.ToString(item.Project_DiaryNumber);

                    objprp.ProjectDoc_InfoCode = Convert.ToInt32(item.ProjectDoc_InfoCode);
                    objprp.Application_SearchTypeFlag = Convert.ToInt32(item.Application_SearchTypeFlag);
                    objprp.RERAnumberRegistration_Input = Convert.ToString(item.RERAnumberRegistration_Input);
                    objprp.ProjectDiaryNumber_Input = Convert.ToString(item.ProjectDiaryNumber_Input);
                    objprp.IsUpdateModifyFlag_ProjectDocument = Convert.ToInt32(item.IsUpdateModifyFlag_ProjectDocument);
                    objprp.ProjectDoc_InfoCode_Input = Convert.ToInt32(item.ProjectDoc_InfoCode_Input);
                    objprp.ProjectDoc_InfoCode_ConfirmInput = Convert.ToInt32(item.ProjectDoc_InfoCode_ConfirmInput);
                    objprp.ProjectDoc_ReferenceNumber_Input = Convert.ToString(item.ProjectDoc_ReferenceNumber_Input);
                    objprp.Remarks_IfAny_Input = Convert.ToString(item.Remarks_IfAny_Input);

                    objprp.Extra01_column = Convert.ToString(item.Extra01_column);
                    objprp.Extra02_column = Convert.ToString(item.Extra02_column);
                    objprp.RoleAccessFlag = Convert.ToString(item.RoleAccessFlag);

                    try
                    {
                        if (objprp.IsUpdateModifyFlag_ProjectDocument == 1)
                        {
                            //Update/modify documents
                            if (!string.IsNullOrEmpty(Convert.ToString(objprp.ProjectDoc_InfoCode_Input)))
                            {
                                if (objprp.ProjectDoc_InfoCode_Input != 0)
                                {
                                    if (objprp.ProjectDoc_InfoCode_Input == objprp.ProjectDoc_InfoCode_ConfirmInput)
                                    {
                                        if (objprp.ProjectDoc_InfoCode_Input != objprp.ProjectDoc_InfoCode)
                                        {
                                            //function(Update/modify documents)
                                            //
                                            var numbers = sdb.Update_CP_ProjectDocuments_FileRearrangementPanel_ByID(objprp, io_UserNam, io_UID, io_UserRole);
                                            if (numbers.Item1)
                                            {
                                                string pNumberValue = numbers.Item2.ToString();
                                                retMessage = "Success! The record updated successfully (" + pNumberValue + ") or has been changed.";
                                                chkappid = 1;
                                                remarkMessage = "Success";
                                                ModelState.Clear();
                                            } 
                                            //                     
                                        }
                                        else
                                        {
                                            status = false;
                                            retMessage = "Invalid! The document name (Update/Modify) is required.";
                                            remarkMessage = "Error";
                                        }
                                    }
                                    else
                                    {
                                        status = false;
                                        retMessage = "Invalid! document name and confirmation document name must match.";
                                        remarkMessage = "Error";
                                    }
                                }
                                else
                                {
                                    status = false;
                                    retMessage = "Invalid! The document name (Update/Modify) is required.";
                                    remarkMessage = "Error";
                                }
                            }
                            else
                            {
                                status = false;
                                retMessage = "Invalid! Something went wrong.";
                                remarkMessage = "Error";
                            }
                        }
                        else
                        {
                            //Add new documents
                            if (!string.IsNullOrEmpty(Convert.ToString(objprp.ProjectDoc_InfoCode_Input)))
                            {
                                if (objprp.ProjectDoc_InfoCode_Input != 0)
                                {
                                    if (objprp.ProjectDoc_InfoCode_Input == objprp.ProjectDoc_InfoCode_ConfirmInput)
                                    {
                                        //function(ADD new documents)
                                        //
                                        status = false;
                                        retMessage = "Invalid! Something went wrong.";
                                        remarkMessage = "Error";
                                        //
                                    }
                                    else
                                    {
                                        status = false;
                                        retMessage = "Invalid! document name and confirmation document name must match.";
                                        remarkMessage = "Error";
                                    }
                                }
                                else
                                {
                                    status = false;
                                    retMessage = "Invalid! The document name (Update/Modify) is required.";
                                    remarkMessage = "Error";
                                }
                            }
                            else
                            {
                                status = false;
                                retMessage = "Invalid! Something went wrong.";
                                remarkMessage = "Error";
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        string exmsg = ex.Message;
                        status = false;
                        retMessage = "Invalid! Something went wrong. (" + exmsg + ")";
                        remarkMessage = "Error";
                    }
                }
            }
            else
            {
                status = false;
                retMessage = "Invalid! Something went wrong.";
                remarkMessage = "Error";
            }

            if (chkappid == null)
                status = false;
            else
                status = true;

            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            objprp.RoleAccessFlag = roletypeFlag;
            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();

            return new JsonResult
            {
                Data = new
                {
                    status = status,
                    statusMessage = retMessage,
                    remarks = remarkMessage
                }
            };
        }

