                    aa.ProjectAddressDistrict = item.ProjectAddressDistrict;

                    aa.Extra01_column = item.Extra01_column;
                    aa.Extra02_column = item.Extra02_column;
                }
                if (aa.prpongoing.Count > 0)
                {
                    chkappid = 1;
                }
                else
                {
                    chkappid = 0;
