                    objprp.AgentDoc_InfoCode = Convert.ToInt32(item.AgentDoc_InfoCode);
                    objprp.Application_SearchTypeFlag = Convert.ToInt32(item.Application_SearchTypeFlag);
                    objprp.RERAnumberRegistration_Input = Convert.ToString(item.RERAnumberRegistration_Input);
                    objprp.AgentDiaryNumber_Input = Convert.ToString(item.AgentDiaryNumber_Input);
                    objprp.IsUpdateModifyFlag_AgentDocument = Convert.ToInt32(item.IsUpdateModifyFlag_AgentDocument);
                    objprp.AgentDoc_InfoCode_Input = Convert.ToInt32(item.AgentDoc_InfoCode_Input);
                    objprp.AgentDoc_InfoCode_ConfirmInput = Convert.ToInt32(item.AgentDoc_InfoCode_ConfirmInput);
                    objprp.AgentDoc_ReferenceNumber_Input = Convert.ToString(item.AgentDoc_ReferenceNumber_Input);
                    objprp.Remarks_IfAny_Input = Convert.ToString(item.Remarks_IfAny_Input);

                    objprp.Extra01_column = Convert.ToString(item.Extra01_column);
                    objprp.Extra02_column = Convert.ToString(item.Extra02_column);
                    objprp.RoleAccessFlag = Convert.ToString(item.RoleAccessFlag);

                    try
                    {
                        if (objprp.IsUpdateModifyFlag_AgentDocument == 1)
                        {
                            //Update/modify documents
                            if (!string.IsNullOrEmpty(Convert.ToString(objprp.AgentDoc_InfoCode_Input)))
                            {
                                if (objprp.AgentDoc_InfoCode_Input != 0)
                                {
                                    if (objprp.AgentDoc_InfoCode_Input == objprp.AgentDoc_InfoCode_ConfirmInput)
                                    {
                                        if (objprp.AgentDoc_InfoCode_Input != objprp.AgentDoc_InfoCode)
                                        {
                                            //function(Update/modify documents)
                                            //
                                            var numbers = sdb.Update_CP_AgentDocuments_FileRearrangementPanel_ByID(objprp, io_UserNam, io_UID, io_UserRole);
                                            if (numbers.Item1)
                                            {
                                                string pNumberValue = numbers.Item2.ToString();
                                                retMessage = "Success! The record updated successfully (" + pNumberValue + ") or has been changed.";
                                                chkappid = 1;
                                                remarkMessage = "Success";
                                                ModelState.Clear();
                                            }
                                            //                     
                                        }
                                        else
                                        {
                                            status = false;
                                            retMessage = "Invalid! The document name (Update/Modify) is required.";
                                            remarkMessage = "Error";
                                        }
                                    }
                                    else
                                    {
                                        status = false;
                                        retMessage = "Invalid! document name and confirmation document name must match.";
                                        remarkMessage = "Error";
                                    }
                                }
                                else
                                {
                                    status = false;
                                    retMessage = "Invalid! The document name (Update/Modify) is required.";
                                    remarkMessage = "Error";
                                }
                            }
                            else
                            {
                                status = false;
                                retMessage = "Invalid! Something went wrong.";
                                remarkMessage = "Error";
                            }
                        }
                        else
                        {
                            //Add new documents
                            if (!string.IsNullOrEmpty(Convert.ToString(objprp.AgentDoc_InfoCode_Input)))
                            {
                                if (objprp.AgentDoc_InfoCode_Input != 0)
                                {
                                    if (objprp.AgentDoc_InfoCode_Input == objprp.AgentDoc_InfoCode_ConfirmInput)
                                    {
                                        //function(ADD new documents)
                                        //
                                        status = false;
                                        retMessage = "Invalid! Something went wrong.";
                                        remarkMessage = "Error";
                                        //
                                    }
                                    else
                                    {
                                        status = false;
                                        retMessage = "Invalid! document name and confirmation document name must match.";
                                        remarkMessage = "Error";
                                    }
                                }
                                else
                                {
                                    status = false;
                                    retMessage = "Invalid! The document name (Update/Modify) is required.";
                                    remarkMessage = "Error";
                                }
                            }
                            else
                            {
                                status = false;
                                retMessage = "Invalid! Something went wrong.";
                                remarkMessage = "Error";
                            }
                        }
                    }
                    catch (Exception ex)
                    {
                        string exmsg = ex.Message;
                        status = false;
                        retMessage = "Invalid! Something went wrong. (" + exmsg + ")";
                        remarkMessage = "Error";
                    }
                }
            }
            else
            {
                status = false;
                retMessage = "Invalid! Something went wrong.";
                remarkMessage = "Error";
            }

            if (chkappid == null)
                status = false;
            else
                status = true;

            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            objprp.RoleAccessFlag = roletypeFlag;
            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();

            return new JsonResult
            {
                Data = new
                {
                    status = status,
                    statusMessage = retMessage,
                    remarks = remarkMessage
                }
            };
        }

