                    aa.IsExtensionRegistration = item.IsExtensionRegistration;
                    aa.RERAnumberExtensionRegUptoDate = item.RERAnumberExtensionRegUptoDate;
                    aa.ProjectDiaryNumber = item.ProjectDiaryNumber;
                    aa.ExtensionRegdDiaryNumber = item.ExtensionRegdDiaryNumber;
                    aa.ProjectName = item.ProjectName;
                    aa.PromoterName = item.PromoterName;
                    aa.ProjectAddressDistrict = item.ProjectAddressDistrict;
                    aa.DName = item.DName;
                    aa.ProjectType = item.ProjectType;

                    aa.ProjectPUC_Reference_IndexID = item.ProjectPUC_Reference_IndexID;
                    aa.ProjectPUC_Reference_ID = item.ProjectPUC_Reference_ID;
                    aa.PUC_ID = item.PUC_ID;
                    aa.PUC_DiaryNumber = item.PUC_DiaryNumber;
                    aa.PUC_ReferencePUC_Name = item.PUC_ReferencePUC_Name;
                    aa.PUC_ReferencePUC_Date = item.PUC_ReferencePUC_Date;
                    aa.PUC_RequestCategoryName = item.PUC_RequestCategoryName;
                    aa.PUC_RequestCategoryID = item.PUC_RequestCategoryID;

                    aa.mFlagPUC_YesNo = item.mFlagPUC_YesNo;
                    aa.mFlagPUC_OpenClosed = item.mFlagPUC_OpenClosed;
                    aa.mFlagPUC_ApprovedNotApproved = item.mFlagPUC_ApprovedNotApproved;
                }
                if (aa.prpongoing.Count > 0)
                {
                    chkappid = 1;
                }
                else
                {
                    chkappid = 0;
                }
            }
            if (chkappid == null || chkappid == 0)
                status = false;
            else
                status = true;

            return new JsonResult
            {
                Data = new
                {
                    status = status,
                    numberObject = aa.prpongoing
                }
            };
        }

