            aa.prpBankMaster = objMaster.Display_Master_BankDetails();
            aa.prpchangerequestcategoryMaster = sdb.Display_CP_ACR_SearchCategoryForMaster_ByID(prmUserRole);
            try
            {
                ModelState.Remove("RERAnumberRegistration_Input");
                ModelState.Remove("ReferenceRegistrationProject_Input");
                ModelState.Remove("ReferenceRegistrationPUC_Input");
                ModelState.Remove("ReferenceNumber_Input");
                if (ModelState.IsValid)
                {
                    inProject_ID = smodel.Related_Project_ID;
                    inPromoter_ID = smodel.Related_Promoter_ID;
                    inApplicationPUC_ID = smodel.RelatedApplicationPUC_ID;
                    inCategoryPUC_ID = smodel.PUC_RequestCategoryID;
                    inProjectDiaryNumber = smodel.ProjectDiaryNumber;
                    inPucDiaryNumber = smodel.PUC_DiaryNumber;
                    
                    string fileExtn = string.Empty;
                    string fileName = string.Empty;
                    string filePath = string.Empty;
                    int errorstate = 0;
                    string errormessage = string.Empty;
                    string prmFileName = string.Empty;
                    string prmFilePath = string.Empty;

                    if (TempData["PrjACRsubmitvalue"].ToString() == "Update")
                    {
                        #region Scan-Copy Update with Path
                        //update with path and photograph
                        if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                        {
                            var files = Request.Files[0];
                            var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg" };
                            fileExtn = Path.GetExtension(files.FileName);
                            if (allowedExtensions.Contains(fileExtn)) 
                            {
                                int size = files.ContentLength;
                                if (size <= 512000)
                                {
                                    #region Declare Variables
                                    var pathserverdata = string.Empty;
                                    var pathindb = string.Empty;
                                    string masterFileServerDoc_SetFilePath = "readwritedataProject";
                                    #endregion
                                    #region UpdateFile Path Creation 
                                    if (!String.IsNullOrEmpty(smodel.ImageCancelledCheque_FilePath))
                                    {
                                        pathindb = smodel.ImageCancelledCheque_FilePath.ToString();
                                    }
                                    else
                                    {
                                        pathindb = masterFileServerDoc_SetFilePath + "\\" + Convert.ToString(inProject_ID) + "\\";
                                    }
                                    pathserverdata = Server.MapPath("~/" + pathindb);

                                    if (!Directory.Exists(pathserverdata))
                                    {
                                        Directory.CreateDirectory(pathserverdata);
                                    }
                                    #endregion
                                    var varfileName = string.Empty;
                                    if (!String.IsNullOrEmpty(smodel.ImageCancelledCheque_FileName))
                                    {
                                        varfileName = smodel.ImageCancelledCheque_FileName.ToString();
                                    }
                                    else
                                    {
                                        varfileName = "SplBCCheque_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + fileExtn;
                                    }

                                    var path = Path.Combine(pathserverdata, varfileName);
                                    files.SaveAs(path);
                                    fileName = varfileName; //Photo_Address
                                    filePath = pathindb;
                                }
                                else
                                {
                                    errormessage = "Scan-Copy Size Should be less than 512KB";
                                    error = "Scan-Copy Size Should be less than 512KB";
                                    errorstate = 1;
                                }
                            }
                            else
                            {
                                errormessage = "Scan-Copy format should be .jpg";
                                error = "Scan-Copy format should be .jpg";
                                errorstate = 1;
                            }
                        }
                        else
                        {
                            errormessage = "Kindly Upload Scan-Copy Document";
                            error = "Kindly Upload Scan-Copy Document";
                            errorstate = 1;

                            //update with same photograph
                            if (Request.Files.Count > 0 && (Request.Files[0].ContentLength == 0))
                            {
                                errorstate = 0;
                            }
                        }
                        #endregion
                        #region Update Method
                        if (errorstate == 0)
                        {
                            if (fileName == string.Empty)
                            {
                                filePath = smodel.ImageCancelledCheque_FilePath;
                                fileName = smodel.ImageCancelledCheque_FileName;
                                fileExtn = Path.GetExtension(smodel.ImageCancelledCheque_FileName);
                            }
                            //ClsMethod_Project_SpecialBankAccountDetails
                            //sdb.Update_Project_SpecialBankAccountDetails(smodel, Photo_Address, FilePathExt);
                            prmFileName = fileName;
                            prmFilePath = filePath;

                            var numbers = sdbspbank.Update_ProjectPUC_SpecialBankAccount(smodel, UserNam, inProject_ID, inPromoter_ID, inApplicationPUC_ID, inProjectDiaryNumber, inCategoryPUC_ID, inPucDiaryNumber, prmFileName, prmFilePath, UID);
                            if (numbers.Item1)
                            {
                                string pNumberValue = numbers.Item2.ToString();
                                TempData["MessagePrjACR"] = "Successfully Updated (" + pNumberValue + ")"; TempData.Keep();
                                TempData["PrjACRsubmitvalue"] = "Update"; TempData.Keep();
                                ModelState.Clear();
                            }
                        }
                        else
                        {
                            TempData["MessagePrjACR"] = "Error: (" + errormessage + ")"; TempData.Keep();
                            TempData["PrjACRsubmitvalue"] = "Update"; TempData.Keep();
                        }
                        #endregion
                    }
                    else
                    {
                        #region Scan-Copy Save with Path
                        if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                        {
                            var files = Request.Files[0];
                            var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg" };
                            fileExtn = Path.GetExtension(files.FileName);  
                            if (allowedExtensions.Contains(fileExtn)) 
                            {
                                int size = files.ContentLength;
                                if (size <= 512000)
                                {
                                    #region Declare Variables
                                    var pathserverdata = string.Empty;
                                    var pathindb = string.Empty;
                                    string masterFileServerDoc_SetFilePath = "readwritedataProject";
                                    #endregion
                                    #region SaveFile Path Creation
                                    pathindb = masterFileServerDoc_SetFilePath + "\\" + Convert.ToString(inProject_ID) + "\\";
                                    pathserverdata = Server.MapPath("~/" + pathindb);

                                    if (!Directory.Exists(pathserverdata))
                                    {
                                        Directory.CreateDirectory(pathserverdata);
                                    }
                                    #endregion
                                    var varfileName = string.Empty;
                                    varfileName = "SplBCCheque_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + fileExtn;
                                    var path = Path.Combine(pathserverdata, varfileName);
                                    files.SaveAs(path);
                                    fileName = varfileName;
                                    filePath = pathindb;
                                }
                                else
                                {
                                    errormessage = "Scan-Copy Size Should be less than 512KB";
                                    error = "Scan-Copy Size Should be less than 512KB";
                                    errorstate = 1;
                                }
                            }
                            else
                            {
                                errormessage = "Scan-Copy format should be .jpg";
                                error = "Scan-Copy format should be .jpg";
                                errorstate = 1;
                            }
                        }
                        else
                        {
                            errormessage = "Kindly Upload Scan-Copy Document";
                            error = "Kindly Upload Scan-Copy Document";
                            errorstate = 1;
                        }
                        #endregion
                        if (errorstate == 0)
                        {
                            if (fileName == string.Empty)
                            {
                                filePath = smodel.ImageCancelledCheque_FilePath;
                                fileName = smodel.ImageCancelledCheque_FileName;
                                fileExtn = Path.GetExtension(smodel.ImageCancelledCheque_FileName);
                            }
                            prmFileName = fileName;
                            prmFilePath = filePath;
                            var numbers = sdbspbank.Add_ProjectPUC_SpecialBankAccount(smodel, UserNam, inProject_ID, inPromoter_ID, inApplicationPUC_ID, inProjectDiaryNumber, inCategoryPUC_ID, inPucDiaryNumber, prmFileName, prmFilePath, UID);
                            if (numbers.Item1)
                            {
                                string pNumberValue = numbers.Item2.ToString();
                                TempData["MessagePrjACR"] = "Successfully Submitted (" + pNumberValue + ")"; TempData.Keep();
                                TempData["PrjACRsubmitvalue"] = "Save"; TempData.Keep();
                                ModelState.Clear();
                            }                            
                        }
                        else
                        {
                            TempData["MessagePrjACR"] = "Error: (" + errormessage + ")"; TempData.Keep();
                            TempData["PrjACRsubmitvalue"] = "Save"; TempData.Keep();
                        }                        
                    }
                }
            }
            catch (Exception ex)
            {
                String e = ex.Message;
            }
            //Role Flag
            string roletypeFlag = getMappingFlagValueforControlPanel();
            aa.RoleAccessFlag = roletypeFlag;
            TempData["returnUrlCPvalue"] = getMappingUrlforControlPanel(); TempData.Keep();

            return View("ACR_ProjectSpecialBankAccountDetails", aa);
        }

