        public void ExportProjectCompletionCertificateToExcel()
        {
            var objXlslist = Session["modelProjectCompletionCertificateMIS"] as List<ClsPrp_ControlPanel_View_ProjectCompletionStatusDetails>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");
            workSheet.TabColor = System.Drawing.Color.Black;
            workSheet.DefaultRowHeight = 12;
            //Header of table  
            //  
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "Last Updated On";
            workSheet.Cells[1, 3].Value = "Diary Number";
            workSheet.Cells[1, 4].Value = "Registration Number";
            workSheet.Cells[1, 5].Value = "Registration Issue Date";
            workSheet.Cells[1, 6].Value = "Registration Upto Date";
            workSheet.Cells[1, 7].Value = "Extension of Registartion Upto Date";
            workSheet.Cells[1, 8].Value = "Project Name";
            workSheet.Cells[1, 9].Value = "Promoter Name";
            workSheet.Cells[1, 10].Value = "PCC Reference Number";
            workSheet.Cells[1, 11].Value = "PCC Reference Date";
            workSheet.Cells[1, 12].Value = "Application Status";
            workSheet.Cells[1, 13].Value = "Prepared By";
            workSheet.Cells[1, 14].Value = "Remarks, If Any";
            //Body of table  
            //  
            string recordItem = string.Empty;
            int recordIndex = 2;
            foreach (var QRcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = QRcodeItem.EventAction_IdentifiedOn.HasValue ? QRcodeItem.EventAction_IdentifiedOn.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 3].Value = QRcodeItem.Completion_DiaryNumber + " of " + QRcodeItem.Project_DiaryNumber;
                workSheet.Cells[recordIndex, 4].Value = QRcodeItem.RERA_RegistrationNumber;
                workSheet.Cells[recordIndex, 5].Value = QRcodeItem.RERAnumberIssueDate.HasValue ? QRcodeItem.RERAnumberIssueDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 6].Value = QRcodeItem.RERAnumberRegUptoDate.HasValue ? QRcodeItem.RERAnumberRegUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty;

                recordItem = QRcodeItem.RERAnumberExtensionRegUptoDate.HasValue? QRcodeItem.RERAnumberExtensionRegUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                if (recordItem == "01-Jan-0001" || recordItem == string.Empty)
                    recordItem = "NA";

                workSheet.Cells[recordIndex, 7].Value = recordItem;
                workSheet.Cells[recordIndex, 8].Value = QRcodeItem.ProjectName ;
                workSheet.Cells[recordIndex, 9].Value = QRcodeItem.PromoterName;
                workSheet.Cells[recordIndex, 10].Value = QRcodeItem.PCC_ReferenceName;
                workSheet.Cells[recordIndex, 11].Value = QRcodeItem.PCC_ReferenceDate.HasValue ? QRcodeItem.PCC_ReferenceDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 12].Value = QRcodeItem.EventAction_Aggregate;
                workSheet.Cells[recordIndex, 13].Value = QRcodeItem.EventAction_IdentifiedBy;
                workSheet.Cells[recordIndex, 14].Value = QRcodeItem.Remarks_IfAny;
                workSheet.Row(recordIndex).Height = 20;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();
            workSheet.Column(13).AutoFit();
            workSheet.Column(14).AutoFit();
            workSheet.Column(15).AutoFit();

            workSheet.Cells["A1:N1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:N1"].Style.Fill.BackgroundColor.SetColor(Color.Yellow);

            using (ExcelRange RangeQR = workSheet.Cells[1, 1, recordIndex - 1, 14])
            {
                RangeQR.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Top.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Left.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Right.Color.SetColor(Color.Black);
                RangeQR.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangeQR.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangeQR.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangeQR.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofPCCstatus_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }
