        #region Common Function
        private string getMappingUrlforControlPanel()
        {
            string vret = string.Empty;
            string pUserRole = string.Empty;
            string pUser_WhoIdentified = string.Empty;

            pUser_WhoIdentified = User.Identity.Name;
            pUserRole = getUserRole();

            vret = "HelpdeskControlPanel/ControlPanelSAInfoDesk";
            // System Analysist
            if (pUserRole == "e583ee7f-aaa3-49bd-afc8-79c877afe591")
            {
                vret = "HelpdeskControlPanel/ControlPanelSAInfoDesk";
            }
            // Programmer
            if (pUserRole == "319a2b07-788f-4f90-9cda-3bca6ed81d3c")
            {
                vret = "HelpdeskControlPanel/ControlPanelInfoDesk";
            }            
            return vret;
        }

        private string getMappingFlagValueforControlPanel()
        {
            string vret = string.Empty;
            string pUserRole = string.Empty;
            string pUser_WhoIdentified = string.Empty;

            pUser_WhoIdentified = User.Identity.Name;
            pUserRole = getUserRole();

            vret = "NA";
            // System Analysist
            if (pUserRole == "e583ee7f-aaa3-49bd-afc8-79c877afe591")
            {
                vret = "SA";
            }
            // Programmer
            if (pUserRole == "319a2b07-788f-4f90-9cda-3bca6ed81d3c")
            {
                vret = "PR";
            }
            return vret;
        }

        private string RegexRemoveEmailCheck(string varSTR)
        {
            
            string oSTR = string.Empty;
            string pattern = "@";
            string replacement = "[at]";            
            Regex rgx = new Regex(pattern);
            oSTR = rgx.Replace(varSTR, replacement);            
            return oSTR;
        }

        private string RegexRemove(string varSTR)
        {
            string oSTR = string.Empty;
            string pattern = "\\s+";
            string replacement = "_";
            Regex rgx = new Regex(pattern);
            oSTR = rgx.Replace(varSTR, replacement);
            return oSTR;
        }

