        public void ExportDuePendingExtensionToExcel()
        {
            var objXlslist = Session["modelProjectExtensionMIS"] as List<ClsPrp_MIS_ProjectRERAnumberExportExcel>;

            Response.ClearContent();
            Response.Buffer = true;
            string strDateFormat = string.Empty;
            strDateFormat = string.Format("{0:yyyy-MMM-dd-hh-mm-ss}", DateTime.Now);

            ExcelPackage excel = new ExcelPackage();
            var workSheet = excel.Workbook.Worksheets.Add("RERA Punjab - Sheet1");
            workSheet.TabColor = System.Drawing.Color.Black;
            workSheet.DefaultRowHeight = 12;
            //Header of table  
            //  
            workSheet.Row(1).Height = 20;
            workSheet.Row(1).Style.HorizontalAlignment = ExcelHorizontalAlignment.Center;
            workSheet.Row(1).Style.Font.Bold = true;

            workSheet.Cells[1, 1].Value = "S.No";
            workSheet.Cells[1, 2].Value = "RERA Registration Number";
            workSheet.Cells[1, 3].Value = "Registration Issue Date";
            workSheet.Cells[1, 4].Value = "Registration Valid Upto Date";
            workSheet.Cells[1, 5].Value = "Project Name";
            workSheet.Cells[1, 6].Value = "Promoter Name";

            workSheet.Cells[1, 7].Value = "Project District";
            workSheet.Cells[1, 8].Value = "Project's Diary Number";            
            workSheet.Cells[1, 9].Value = "Authorized Person Name";
            workSheet.Cells[1, 10].Value = "Authorized Person Email";
            workSheet.Cells[1, 11].Value = "Authorized Person Mobile Number";
            workSheet.Cells[1, 12].Value = "Promoter Weblink";
            workSheet.Cells[1, 13].Value = "Remarks, If Any";

            //Body of table  
            //  
            int recordIndex = 2;
            foreach (var PCCcodeItem in objXlslist)
            {
                workSheet.Cells[recordIndex, 1].Value = (recordIndex - 1).ToString();
                workSheet.Cells[recordIndex, 2].Value = PCCcodeItem.RERAnumberRegistration;
                workSheet.Cells[recordIndex, 3].Value = PCCcodeItem.RERAnumberIssueDate.HasValue ? PCCcodeItem.RERAnumberIssueDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 4].Value = PCCcodeItem.RERAnumberRegUptoDate.HasValue ? PCCcodeItem.RERAnumberRegUptoDate.Value.ToString("dd-MMM-yyyy") : string.Empty;
                workSheet.Cells[recordIndex, 5].Value = PCCcodeItem.ProjectName;
                workSheet.Cells[recordIndex, 6].Value = PCCcodeItem.PromoterName;

                workSheet.Cells[recordIndex, 7].Value = PCCcodeItem.Project_AddressDistrictName;
                workSheet.Cells[recordIndex, 8].Value = PCCcodeItem.ProjectRegDiaryNumber_Name;
                workSheet.Cells[recordIndex, 9].Value = PCCcodeItem.AuthorizedPerson_FirstName.Trim() + " " + PCCcodeItem.AuthorizedPerson_LastName.Trim();
                workSheet.Cells[recordIndex, 10].Value = PCCcodeItem.AuthorizedPerson_Email;
                workSheet.Cells[recordIndex, 11].Value = PCCcodeItem.AuthorizedPerson_Mobile;
                workSheet.Cells[recordIndex, 12].Value = PCCcodeItem.PromoterWebLink;
                workSheet.Cells[recordIndex, 13].Value = "";

                workSheet.Row(recordIndex).Height = 15;
                recordIndex++;
            }
            workSheet.Column(1).AutoFit();
            workSheet.Column(2).AutoFit();
            workSheet.Column(3).AutoFit();
            workSheet.Column(4).AutoFit();
            workSheet.Column(5).AutoFit();
            workSheet.Column(6).AutoFit();
            workSheet.Column(7).AutoFit();
            workSheet.Column(8).AutoFit();
            workSheet.Column(9).AutoFit();
            workSheet.Column(10).AutoFit();
            workSheet.Column(11).AutoFit();
            workSheet.Column(12).AutoFit();
            workSheet.Column(13).AutoFit();

            workSheet.Cells["A1:M1"].Style.Fill.PatternType = ExcelFillStyle.Solid;
            workSheet.Cells["A1:M1"].Style.Fill.BackgroundColor.SetColor(Color.Yellow);

            using (ExcelRange RangePCC = workSheet.Cells[1, 1, recordIndex - 1, 13])
            {
                RangePCC.Style.Border.Top.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Top.Color.SetColor(Color.Black);
                RangePCC.Style.Border.Left.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Left.Color.SetColor(Color.Black);
                RangePCC.Style.Border.Right.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Right.Color.SetColor(Color.Black);
                RangePCC.Style.Border.Bottom.Style = ExcelBorderStyle.Thin;
                RangePCC.Style.Border.Bottom.Color.SetColor(Color.Black);
                RangePCC.Style.HorizontalAlignment = ExcelHorizontalAlignment.Left;
                RangePCC.Style.VerticalAlignment = ExcelVerticalAlignment.Top;
            }

            using (var memoryStream = new MemoryStream())
            {
                Response.ContentType = "application/ms-excel";
                Response.Charset = "";
                Response.AddHeader("content-disposition", "attachment; filename=ListofProjectsDueForExtensionCompletion_" + strDateFormat + ".xls");
                excel.SaveAs(memoryStream);
                memoryStream.WriteTo(Response.OutputStream);
                Response.Flush();
                Response.End();
            }
        }
