        [HttpGet]
        public ActionResult ProjectExtensionInfoEventInsert()//Int64 projectId, string DiaryNumber)
        {
            ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
            ClsPrp_ExtensionAuthorityDesk_ProjectEventLog aa = new ClsPrp_ExtensionAuthorityDesk_ProjectEventLog();

            string userRole = string.Empty;
            userRole = getUserRole();
            //to bind subCheckList master
            aa.EventMaster = sdb.Display_AuthorityDesk_ProjectExtensionEvent_Master(userRole);

            if (Session["zipExtensionProjectDiaryNumber"] != null)
            {
                string ExtensionProjectDiaryNumber = Session["zipExtensionProjectDiaryNumber"].ToString();
                string ExtensionProjectName = Session["zipExtensionProjectName"].ToString();
                Int64? ExtensionProjectID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                DateTime? ExtensionLastModifiedOn = Convert.ToDateTime(Session["zipExtensionLastModifiedOn"]);
                Int64? ExtensionPromoterID = Convert.ToInt64(Session["zipExtensionPromoterID"]);

                aa.Related_Promoter_ID = (ExtensionPromoterID != null) ? Convert.ToInt64(ExtensionPromoterID) : 0;
                aa.Related_Project_ID = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
                aa.Promoter_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                aa.Project_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                aa.ProjectName = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
                aa.ProjectLastModifiedOn = ExtensionLastModifiedOn;
            }
            else
            {
                aa.Related_Promoter_ID = 0;
                aa.Related_Project_ID = 0;
                aa.Promoter_DiaryNumber = "";
                aa.Project_DiaryNumber = "";
                aa.ProjectName = "";
            }
            TempData["ExtensionFormEventSubmitMessage"] = "";

            return View("ProjectExtensionInfoEventInsert", aa);
        }

        [HttpGet]
        public ActionResult ProjectExtensionInfoEventInsertAction(string ExtensionProjectDiaryNumber, string ExtensionProjectName, Int64? ExtensionProjectID, DateTime? ExtensionLastModifiedOn, Int64? ExtensionPromoterID)
        {

            Session["zipExtensionProjectDiaryNumber"] = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
            Session["zipExtensionProjectName"] = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
            Session["zipExtensionProjectID"] = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
            Session["zipExtensionLastModifiedOn"] = ExtensionLastModifiedOn;
            Session["zipExtensionPromoterID"] = (ExtensionPromoterID != null) ? Convert.ToInt64(ExtensionPromoterID) : 0;


            ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
            ClsPrp_ExtensionAuthorityDesk_ProjectEventLog aa = new ClsPrp_ExtensionAuthorityDesk_ProjectEventLog();

            string userRole = string.Empty;
            userRole = getUserRole();
            //to bind subCheckList master
            aa.EventMaster = sdb.Display_AuthorityDesk_ProjectExtensionEvent_Master(userRole);

            aa.Related_Promoter_ID = (ExtensionPromoterID != null) ? Convert.ToInt64(ExtensionPromoterID) : 0;
            aa.Related_Project_ID = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
            aa.Promoter_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
            aa.Project_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
            aa.ProjectName = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
            aa.ProjectLastModifiedOn = ExtensionLastModifiedOn;

            TempData["ExtensionFormEventSubmitMessage"] = "";

            return View("ProjectExtensionInfoEventInsert", aa);
        }

        [HttpPost]
        public ActionResult ProjectExtensionInfoEventInsert(ClsPrp_ExtensionAuthorityDesk_ProjectEventLog smodel)
        {
            ClsPrp_ExtensionAuthorityDesk_ProjectEventLog aa = new ClsPrp_ExtensionAuthorityDesk_ProjectEventLog();
            try
            {
                if (ModelState.IsValid)
                {
                    ClsExtnMethod_ProjectExtensionHelpdesk sdb = new ClsExtnMethod_ProjectExtensionHelpdesk();
                    string pUserRole = string.Empty;
                    pUserRole = getUserRole();
                    string pUser_WhoIdentified = User.Identity.Name;

                    if (sdb.Add_ProjectExtensionForm_InfoEvent(smodel, pUserRole, pUser_WhoIdentified))
                    {
                        ViewBag.Message = "Details Added Successfully";
                        ModelState.Clear();

                        TempData["ExtensionFormEventSubmitMessage"] = "Application Performa successfully Submitted.";
                        TempData["ExtensionFormEventSubmitMessageMappingUrlFlag"] = getMappingUrlByProjectExtensionEvent();
                    }

                    //to bind subCheckList master
                    aa.EventMaster = sdb.Display_AuthorityDesk_ProjectExtensionEvent_Master(pUserRole);

                    if (Session["zipExtensionProjectDiaryNumber"] != null)
                    {
                        string ExtensionProjectDiaryNumber = Session["zipExtensionProjectDiaryNumber"].ToString();
                        string ExtensionProjectName = Session["zipExtensionProjectName"].ToString();
                        Int64? ExtensionProjectID = Convert.ToInt64(Session["zipExtensionProjectID"]);
                        DateTime? ExtensionLastModifiedOn = Convert.ToDateTime(Session["zipExtensionLastModifiedOn"]);
                        Int64? ExtensionPromoterID = Convert.ToInt64(Session["zipExtensionPromoterID"]);

                        aa.Related_Promoter_ID = (ExtensionPromoterID != null) ? Convert.ToInt64(ExtensionPromoterID) : 0;
                        aa.Related_Project_ID = (ExtensionProjectID != null) ? Convert.ToInt64(ExtensionProjectID) : 0;
                        aa.Promoter_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                        aa.Project_DiaryNumber = (String.IsNullOrEmpty(ExtensionProjectDiaryNumber) ? "" : ExtensionProjectDiaryNumber);
                        aa.ProjectName = (String.IsNullOrEmpty(ExtensionProjectName) ? "" : ExtensionProjectName);
                        aa.ProjectLastModifiedOn = ExtensionLastModifiedOn;
                    }
                    else
                    {
                        aa.Related_Promoter_ID = 0;
                        aa.Related_Project_ID = 0;
                        aa.Promoter_DiaryNumber = "";
                        aa.Project_DiaryNumber = "";
                        aa.ProjectName = "";
                    }
                }            
                return View("ProjectExtensionInfoEventInsert", aa);
            }
            catch (Exception ex)
            {
                TempData["ExtensionFormEventSubmitMessage"] = "Sorry, Application Performa is pending";
                TempData["ExtensionFormEventSubmitMessageMappingUrlFlag"] = getMappingUrlByProjectExtensionEvent();

                return View("ProjectExtensionInfoEventInsert", aa);
            }
        }

        public JsonResult GetProjectExtensionEventDescriptionMasterByCode(string EventCode)
        {
            int Id = 0;
            if (EventCode != "")
                Id = Convert.ToInt32(EventCode);

            ClsExtnMethod_ProjectExtensionHelpdesk objCode = new ClsExtnMethod_ProjectExtensionHelpdesk();
            var EventCodeDiv = objCode.Display_AuthorityDesk_EventDescription_MasterDetailsByCode(Id);

            return Json(EventCodeDiv);
        }

        private string getMappingUrlByProjectExtensionEvent()
        {
            string vret = string.Empty;
            string pUserRole = string.Empty;
            string pUser_WhoIdentified = string.Empty;

            pUser_WhoIdentified = User.Identity.Name;
            pUserRole = getUserRole();

            vret = "ResetFlag";

            // Chairperson OR membersg OR memberjsk
            if (pUser_WhoIdentified == "chairperson" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskReviewCL";
            }
            if (pUser_WhoIdentified == "membersg" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskReviewCL";
            }
            if (pUser_WhoIdentified == "memberjsk" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskReviewCL";
            }

            // Secrett RERA
            if (pUser_WhoIdentified == "secyrera" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskReviewCL";
            }
            if (pUser_WhoIdentified == "consultantrera" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskCheckList";
            }
            if (pUser_WhoIdentified == "mngradminrera" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskCheckList";
            }


            // ReraDesk
            if (pUserRole == "7b9d725a-b33c-4aba-934a-bee1ec13f684")
            {
                vret = "Helpdesk/ProjectExtensionInfoDesk";
            }

            // System Analysist
            if (pUserRole == "e583ee7f-aaa3-49bd-afc8-79c877afe591")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskIssueRERAid";
            }

            // System Counseltent
            if (pUser_WhoIdentified == "pbreraconsultant" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskCheckList";
            }
            if (pUser_WhoIdentified == "secttrera" && pUserRole == "15ac7786-a35e-46a3-ae19-8befd003dcfd")
            {
                vret = "Helpdesk/ProjectExtensionInfoDeskCheckList";
            }
            return vret;
        }
