        [HttpPost]
        public ActionResult Add_ExtensionProjectRegistrationCertificate(ClsPrp_ExtensionAuthorityDesk_ProjectExtnForm_RegistrationCertificate smodel)
        {
            string extractFileName = string.Empty;
            string userRole = string.Empty;
            userRole = getUserRole();
            string UserNam = User.Identity.Name;

            Int64 ccProjectID = 0;
            Int64 ccPromoterID = 0;
            DateTime? ccLastmodifiedDate = DateTime.Now;
            string ccProjectName = string.Empty;
            string ccProjectDiaryNumber = string.Empty;
            string ccExtnDiaryNumber = string.Empty;
            string ccRegistrationNumber = string.Empty;

            if (Session["zipExtnProjectDiaryNumber"] != null)
            {
                string mmProjectDiaryNumber = Session["zipExtnProjectDiaryNumber"].ToString();
                string mmExtensionFormProjectDiaryNumber = Session["zipExtensionFormDiaryNumber"].ToString();
                string mmExtnProjectName = Session["zipExtnProjectName"].ToString();
                Int64? mmExtnProjectID = Convert.ToInt64(Session["zipExtnProjectID"]);
                DateTime? mmExtnLastModifiedOn = Convert.ToDateTime(Session["zipExtnLastModifiedOn"]);
                Int64? mmExtnPromoterID = Convert.ToInt64(Session["zipExtnPromoterID"]);
                string mmExtnProjectRegistrationNumber = Session["zipExtnProjectRegistrationNumber"].ToString();

                ccPromoterID = (mmExtnPromoterID != null) ? Convert.ToInt64(mmExtnPromoterID) : 0;
                ccProjectID = (mmExtnProjectID != null) ? Convert.ToInt64(mmExtnProjectID) : 0;
                ccProjectDiaryNumber = (String.IsNullOrEmpty(mmProjectDiaryNumber) ? "" : mmProjectDiaryNumber);
                ccExtnDiaryNumber = (String.IsNullOrEmpty(mmExtensionFormProjectDiaryNumber) ? "" : mmExtensionFormProjectDiaryNumber);
                ccProjectName = (String.IsNullOrEmpty(mmExtnProjectName) ? "" : mmExtnProjectName);
                ccLastmodifiedDate = mmExtnLastModifiedOn;
                ccRegistrationNumber = (String.IsNullOrEmpty(mmExtnProjectRegistrationNumber) ? "" : mmExtnProjectRegistrationNumber);
            }

            //Save & Update
            #region

            String extractFileExt = String.Empty;
            string extractFilePath = string.Empty;
            string error = string.Empty;
            int errorstate = 0;

            if (TempData["submitvalue"].ToString() == "Update")
            {
                #region PhotoCertificate Update with Path
                if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                {
                    var files = Request.Files[0];
                    var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg", ".PDF", ".pdf", ".Pdf" };
                    extractFileExt = Path.GetExtension(files.FileName); //getting the extension(ex-.jpg)  
                    if (allowedExtensions.Contains(extractFileExt)) //check what type of extension  
                    {
                        int size = files.ContentLength;
                        if (size <= 1024000)
                        {
                            #region Declare Variables
                            var pathpromoterdata = string.Empty;
                            var pathindb = "";
                            string masterAuthorityDoc_SetFilePath = "readwritePrjEnCert";
                            #endregion
                            #region UpdateFile Path Creation 
                            if (!String.IsNullOrEmpty(smodel.ProjectRERAcert_FilePath))
                            {
                                pathindb = smodel.ProjectRERAcert_FilePath.ToString();
                            }
                            else
                            {
                                pathindb = masterAuthorityDoc_SetFilePath + "\\" + Convert.ToString(ccProjectID) + "\\";
                            }
                            pathpromoterdata = Server.MapPath("~/" + pathindb);

                            if (!Directory.Exists(pathpromoterdata))
                            {
                                Directory.CreateDirectory(pathpromoterdata);
                            }
                            #endregion

                            var fileName = string.Empty;
                            if (!String.IsNullOrEmpty(smodel.ProjectRERAcert_FileName))
                            {
                                fileName = smodel.ProjectRERAcert_FileName.ToString();
                            }
                            else
                            {
                                fileName = "EnPRJcert_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + extractFileExt;
                            }

                            var path = Path.Combine(pathpromoterdata, fileName);
                            files.SaveAs(path);
                            extractFileName = fileName;
                            extractFilePath = pathindb;
                            smodel.ProjectRERAcert_FileFormat = extractFileExt;
                        }
                        else
                        {
                            TempData["notice"] = "Document size should be less than 1MB";
                            error = "Document size should be less than 1MB";
                            errorstate = 1;
                        }
                    }
                    else
                    {
                        TempData["notice"] = "Document format should be .jpg or .pdf";
                        error = "Document format should be .jpg or .pdf";
                        errorstate = 1;
                    }
                }
                else
                {
                    TempData["notice"] = "Invalid! Please Upload Document";
                    error = "Invalid! Please Upload Document";
                    errorstate = 1;

                    //update with same photograph
                    if (Request.Files.Count > 0 && (Request.Files[0].ContentLength == 0))
                    {
                        errorstate = 0;
                    }

                }
                #endregion
                if (errorstate == 0)
                {
                    if (ModelState.IsValid)
                    {
                        if (extractFileName == string.Empty)
                        {
                            extractFileName = smodel.ProjectRERAcert_FileName;
                            extractFileExt = smodel.ProjectRERAcert_FileFormat;
                            extractFilePath = smodel.ProjectRERAcert_FilePath;
                        }
                        try
                        {
                            ClsExtnMethod_ProjectExtensionRERAcertificate sdb = new ClsExtnMethod_ProjectExtensionRERAcertificate();
                            sdb.Update_LDR_ExtensionFormProject_RERAcertifcate_DiaryNumber(smodel, ccProjectID, ccPromoterID, extractFileName, extractFilePath, UserNam);
                            TempData["message"] = "Updated Successfully";

                            return RedirectToAction("Add_ExtensionProjectRegistrationCertificate");
                        }
                        catch (Exception ex)
                        {
                            ex.ToString();
                            return View();
                        }
                    }
                    return RedirectToAction("Add_ExtensionProjectRegistrationCertificate");
                }
                else
                {
                    return RedirectToAction("Add_ExtensionProjectRegistrationCertificate"); 
                }
            }
            else
            {
                #region PhotoCertificate Save with Path
                if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                {
                    var files = Request.Files[0];
                    var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg", ".PDF", ".pdf", ".Pdf" };
                    extractFileExt = Path.GetExtension(files.FileName); //getting the extension(ex-.jpg)  
                    if (allowedExtensions.Contains(extractFileExt)) //check what type of extension  
                    {
                        int size = files.ContentLength;
                        if (size <= 1024000)
                        {
                            #region Declare Variables
                            var pathpromoterdata = "";
                            var pathindb = "";
                            string masterAuthorityDoc_SetFilePath = "readwritePrjEnCert";
                            #endregion

                            #region SaveFile Path Creation
                            pathindb = masterAuthorityDoc_SetFilePath + "\\" + Convert.ToString(ccProjectID) + "\\";
                            pathpromoterdata = Server.MapPath("~/" + pathindb);

                            if (!Directory.Exists(pathpromoterdata))
                            {
                                Directory.CreateDirectory(pathpromoterdata);
                            }
                            #endregion

                            var fileName = string.Empty;
                            fileName = "EnPRJcert_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + extractFileExt;
                            var path = Path.Combine(pathpromoterdata, fileName);
                            files.SaveAs(path);
                            extractFileName = fileName;
                            extractFilePath = pathindb;
                            smodel.ProjectRERAcert_FileFormat = extractFileExt;
                        }
                        else
                        {
                            TempData["notice"] = "Document size should be less than 1MB";
                            error = "Document size should be less than 1MB";
                            errorstate = 1;
                        }
                    }
                    else
                    {
                        TempData["notice"] = "Document format should be .jpg or .pdf";
                        error = "Document format should be .jpg or .pdf";
                        errorstate = 1;
                    }
                }
                else
                {
                    TempData["notice"] = "Invalid! Please Upload Photograph";
                    error = "Invalid! Please Upload Photograph";
                    errorstate = 1;
                }
                #endregion
                try
                {
                    if (errorstate == 0)
                    {
                        if (ModelState.IsValid)
                        {
                            if (extractFileName == string.Empty)
                            {
                                extractFileName = smodel.ProjectRERAcert_FileName;
                                extractFileExt = smodel.ProjectRERAcert_FileFormat;
                                extractFilePath = smodel.ProjectRERAcert_FilePath;
                            }
                            ClsExtnMethod_ProjectExtensionRERAcertificate sdb = new ClsExtnMethod_ProjectExtensionRERAcertificate();
                            if (sdb.Add_LDR_ExtensionFormProject_RERAcertifcate_DiaryNumber(smodel, ccProjectID, ccPromoterID, extractFileName, extractFilePath, UserNam))
                            {
                                TempData["message"] = "Successfully Saved";
                                ModelState.Clear();
                            }
                        }
                        return RedirectToAction("Add_ExtensionProjectRegistrationCertificate");
                    }
                    else
                    {
                        return RedirectToAction("Add_ExtensionProjectRegistrationCertificate");                        
                    }
                }
                catch (Exception ex)
                {
                    ex.ToString();
                    return View();
                }
            }
            #endregion
        }

