        //Public-Unpublic Handler (Extension of Registration Documents By Index)
        public JsonResult PublicUnpublicHandler_ProjectExtensionCertificateByIndex(string prmprojectId, string prmpromoterId, string prmprojectcertindexId, string prmprojectcertId, string prmPublicUnpublic)
        {
            Int32 retvaluePublicUnpublic = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 PromoterCode = 0;
                Int64 ProjectCertificateIndexCode = 0;
                Int32 ProjectCertificateCode = 0;
                string PublicUnpublicCode = "1"; //Yes(1) Public View
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmprojectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(prmprojectId);
                }
                if (prmpromoterId != string.Empty)
                {
                    PromoterCode = Convert.ToInt64(prmpromoterId);
                }
                if (prmprojectcertindexId != string.Empty)
                {
                    ProjectCertificateIndexCode = Convert.ToInt32(prmprojectcertindexId);
                }
                if (prmprojectcertId != string.Empty)
                {
                    ProjectCertificateCode = Convert.ToInt32(prmprojectcertId);
                }
                if (prmPublicUnpublic != string.Empty)
                {
                    if (prmPublicUnpublic == "true")
                    {
                        // has class YPV(1), request for UnPublicView. hence set NPV(0)
                        PublicUnpublicCode = Convert.ToString("0");
                    }
                    else if (prmPublicUnpublic == "false")
                    {
                        // has class NPV(0), request for PublicView. hence set YPV(1)
                        PublicUnpublicCode = Convert.ToString("1");
                    }
                    else
                    {
                        // has class unknown, request for PublicView. hence set YPV(1)
                        PublicUnpublicCode = Convert.ToString("1");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Extension of registration of project certificate details";
                switch (PublicUnpublicCode)
                {
                    case "0": //NPV
                        RelatedPVMsg = "UnPublicView request";
                        break;
                    case "1": //YPV
                        RelatedPVMsg = "PublicView request";
                        break;
                    default:
                        RelatedPVMsg = "others (PublicView)";
                        break;
                }
                #endregion
                ClsExtnMethod_ProjectExtensionRERAcertificate sdb = new ClsExtnMethod_ProjectExtensionRERAcertificate();
                retvaluePublicUnpublic = sdb.Update_PublicUnpublicHandler_ProjectExtensionCertificateByIndex(ProjectCode, ProjectCertificateIndexCode, ProjectCertificateCode, PublicUnpublicCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvaluePublicUnpublic; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Enabled successfully public view of project certificate documents.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Disabled successfully public view of project certificate documents.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
        #endregion

