                        //Object Value (Input)
                        parmRelated_ProjectID = Convert.ToInt64(item.Related_Project_ID);
                        parmRelated_PromoterID = Convert.ToInt64(item.Related_Promoter_ID);
                        parmNumberOptions_Flag = Convert.ToInt32(item.RegistrationNumberOptions_Input);
                        parmProjectType_Flag = Convert.ToString(item.ProjectType_Input);
                        parmRegistration_IssueDate = Convert.ToDateTime(item.RegistrationIssueDate_Input);
                        parmRegistration_UptoDate = Convert.ToDateTime(item.RegistrationValidUptoDate_Input);
                        parmIsDraft = Convert.ToInt32(item.IsDraft);

                        aa.prpongoing = sdbcalc.Extract_AuthDesk_ProjectRegistrationNumber_ByProjectID(parmRelated_ProjectID, parmRelated_PromoterID, parmNumberOptions_Flag, parmProjectType_Flag, parmRegistration_IssueDate, parmRegistration_UptoDate, UserNam);
