        public ActionResult Add_ProjectRERAcertificateDetails(ClsPrp_AuthorityDesk_ProjectRERA_Certificate smodel)
        {           
            string Photo_Address = string.Empty;
            string userRole = string.Empty;
            userRole = getUserRole();
            string UserNam = User.Identity.Name;

            Int64 ccProjectID = 0;
            Int64 ccPromoterID = 0;
            DateTime? ccLastmodifiedDate = DateTime.Now;
            string ccProjectName = string.Empty;
            string ccProjectDiaryNumber = string.Empty;

            if (Session["zipProjectDiaryNumber"] != null)
            {
                string mmProjectDiaryNumber = Session["zipProjectDiaryNumber"].ToString();
                string mmProjectName = Session["zipProjectName"].ToString();
                Int64? mmProjectID = Convert.ToInt64(Session["zipProjectID"]);
                DateTime? mmLastModifiedOn = Convert.ToDateTime(Session["zipLastModifiedOn"]);
                Int64? mmPromoterID = Convert.ToInt64(Session["zipPromoterID"]);

                ccPromoterID = (mmPromoterID != null) ? Convert.ToInt64(mmPromoterID) : 0;
                ccProjectID = (mmProjectID != null) ? Convert.ToInt64(mmProjectID) : 0;
                ccProjectDiaryNumber = (String.IsNullOrEmpty(mmProjectDiaryNumber) ? "" : mmProjectDiaryNumber);
                ccProjectName = (String.IsNullOrEmpty(mmProjectName) ? "" : mmProjectName);
                ccLastmodifiedDate = mmLastModifiedOn;
            }

            //Save & Update
            #region

            String ext = String.Empty;
            string FilePathExt = string.Empty;
            string error = string.Empty;
            int errorstate = 0;

            if (TempData["submitvalue"].ToString() == "Update")
            {
                #region PhotoCertificate Update with Path
                if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                {
                    var files = Request.Files[0];
                    var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg", ".PDF", ".pdf", ".Pdf" };
                    ext = Path.GetExtension(files.FileName); //getting the extension(ex-.jpg)  
                    if (allowedExtensions.Contains(ext)) //check what type of extension  
                    {
                        int size = files.ContentLength;
                        if (size <= 1024000)
                        {

                            #region Declare Variables
                            var pathpromoterdata = "";
                            var pathindb = "";
                            string masterPromoterDoc_SetFilePath = "readwritePRJCert";
                            #endregion

                            #region UpdateFile Path Creation 
                            if (!String.IsNullOrEmpty(smodel.ProjectRERAcert_FilePath))
                            {
                                pathindb = smodel.ProjectRERAcert_FilePath.ToString();
                            }
                            else
                            {
                                pathindb = masterPromoterDoc_SetFilePath + "\\" + Convert.ToString(ccProjectID) + "\\";
                            }
                            pathpromoterdata = Server.MapPath("~/" + pathindb);

                            if (!Directory.Exists(pathpromoterdata))
                            {
                                Directory.CreateDirectory(pathpromoterdata);
                            }
                            #endregion

                            var fileName = string.Empty;
                            if (!String.IsNullOrEmpty(smodel.ProjectRERAcert_FileName))
                            {
                                fileName = smodel.ProjectRERAcert_FileName.ToString();
                            }
                            else
                            {
                                fileName = "PRJcert_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + ext;
                            }

                            var path = Path.Combine(pathpromoterdata, fileName);
                            files.SaveAs(path);
                            Photo_Address = fileName;
                            FilePathExt = pathindb;

                        }
                        else
                        {
                            TempData["notice"] = "Photo Size Should be less than 1MB";
                            error = "Photo Size Should be less than 1MB";
                            errorstate = 1;
                        }
                    }
                    else
                    {
                        TempData["notice"] = "Photo format should be .jpg or .pdf";
                        error = "Photo format should be .jpg or .pdf";
                        errorstate = 1;
                    }
                }
                else
                {
                    TempData["notice"] = "Kindly Upload Photograph";
                    error = "Kindly Upload Photograph";
                    errorstate = 1;

                    //update with same photograph
                    if (Request.Files.Count > 0 && (Request.Files[0].ContentLength == 0))
                    {
                        errorstate = 0;
                    }

                }
                #endregion
                if (errorstate == 0)
                {
                    if (ModelState.IsValid)
                    {
                        if (Photo_Address == "")
                        {
                            Photo_Address = smodel.ProjectRERAcert_FileName;
                            ext = smodel.ProjectRERAcert_FilePath;
                            FilePathExt = smodel.ProjectRERAcert_FilePath;
                        }
                        try
                        {
                            ClsMethod_ViewAdd_ProjectRERAcertificate sdb = new ClsMethod_ViewAdd_ProjectRERAcertificate();
                            sdb.Update_LDR_Project_RERAcertifcate_DiaryNumber(smodel, ccProjectID, ccPromoterID, Photo_Address, FilePathExt, UserNam, userRole, ccProjectDiaryNumber);
                            TempData["message"] = "Details updated Successfully"; 
                                                       
                            return RedirectToAction("Add_ProjectRERAcertificateDetails");
                        }
                        catch (Exception ex)
                        {
                            ex.ToString();
                            return View();
                        }
                    }
                    return RedirectToAction("Add_ProjectRERAcertificateDetails");
                }
                else
                {
                    return RedirectToAction("Add_ProjectRERAcertificateDetails");
                }
            }
            else
            {
                #region PhotoCertificate Save with Path
                if (Request.Files.Count > 0 && (Request.Files[0].ContentLength != 0))
                {
                    var files = Request.Files[0];
                    var allowedExtensions = new[] { ".Jpg", ".jpg", ".JPG", ".jpeg", ".JPEG", ".Jpeg", ".PDF", ".pdf", ".Pdf" };
                    ext = Path.GetExtension(files.FileName); //getting the extension(ex-.jpg)  
                    if (allowedExtensions.Contains(ext)) //check what type of extension  
                    {
                        int size = files.ContentLength;
                        if (size <= 1024000)
                        {

                            #region Declare Variables
                            var pathpromoterdata = "";
                            var pathindb = "";
                            string masterPromoterDoc_SetFilePath = "readwritePRJCert";
                            #endregion

                            #region SaveFile Path Creation
                            pathindb = masterPromoterDoc_SetFilePath + "\\" + Convert.ToString(ccProjectID) + "\\";
                            pathpromoterdata = Server.MapPath("~/" + pathindb);

                            if (!Directory.Exists(pathpromoterdata))
                            {
                                Directory.CreateDirectory(pathpromoterdata);
                            }
                            #endregion

                            var fileName = string.Empty;
                            fileName = "PRJcert_" + SaveFileDatePrefix() + Guid.NewGuid().ToString() + ext;
                            var path = Path.Combine(pathpromoterdata, fileName);
                            files.SaveAs(path);
                            Photo_Address = fileName;
                            FilePathExt = pathindb;

                        }
                        else
                        {
                            TempData["notice"] = "Photo Size Should be less than 1MB";
                            error = "Photo Size Should be less than 1MB";
                            errorstate = 1;
                        }
                    }
                    else
                    {
                        TempData["notice"] = "Photo format should be .jpg or .pdf";
                        error = "Photo format should be .jpg or .pdf";
                        errorstate = 1;
                    }
                }
                else
                {
                    TempData["notice"] = "Kindly Upload Photograph";
                    error = "Kindly Upload Photograph";
                    errorstate = 1;
                }
                #endregion
                try
                {
                    if (errorstate == 0)
                    {
                        if (ModelState.IsValid)
                        {
                            if (Photo_Address == "")
                            {
                                Photo_Address = smodel.ProjectRERAcert_FileName;
                                ext = smodel.ProjectRERAcert_FilePath;
                                FilePathExt = smodel.ProjectRERAcert_FilePath;
                            }
                            ClsMethod_ViewAdd_ProjectRERAcertificate sdb = new ClsMethod_ViewAdd_ProjectRERAcertificate();
                            if (sdb.Add_LDR_Project_RERAcertifcate_DiaryNumber(smodel, ccProjectID, ccPromoterID, Photo_Address, FilePathExt, UserNam, userRole, ccProjectDiaryNumber))
                            {
                                TempData["message"] = " Details Added Successfully";
                                ModelState.Clear();
                            }
                        }
                        return RedirectToAction("Add_ProjectRERAcertificateDetails");
                    }
                    else
                    {
                        return RedirectToAction("Add_ProjectRERAcertificateDetails");
                    }
                }
                catch (Exception ex)
                {
                    ex.ToString();
                    return View();
                }
            }
            #endregion
        }

