        #region View Project Documents
        [HttpGet]
        public ActionResult Display_ProjectDocuments()
        {
            ClsMethod_View_ProjectDocuments sdb = new ClsMethod_View_ProjectDocuments();
            Clsprp_AuthDesk_View_ProjectDocuments aa = new Clsprp_AuthDesk_View_ProjectDocuments();
            string userRole = string.Empty;
            Int64 ProjectID = 0;
            userRole = getUserRole();
            if (Session["zipProjectDiaryNumber"] != null)
            {
                Int64? Project_ID = Convert.ToInt64(Session["zipProjectID"]);
                ProjectID = (Project_ID != null) ? Convert.ToInt64(Project_ID) : 0;
            }
            
            aa.prpongoing = sdb.Display_Project_Documents_ByProjectId(ProjectID);

            #region Lock - Unlock (Logic Display Message)
            bool var_Anydocopen = false;
            bool var_Alldocclosed = false;
            bool var_Anydocpermanent = false;            

            if (aa.prpongoing.Count == 0)
            {
                aa.IsDraftAllDocuments = 0;
            }                     

            foreach (var item in aa.prpongoing)
            {
                aa.ProjectDoc_IndexID = item.ProjectDoc_IndexID;
                aa.ProjectDoc_ID = item.ProjectDoc_ID;
                aa.Promoter_ID = item.Promoter_ID;
                aa.Project_ID = item.Project_ID;
                aa.ProjectDoc_InfoCode = item.ProjectDoc_InfoCode;
                aa.ProjectDoc_InfoName = item.ProjectDoc_InfoName;
                aa.ProjectDoc_RelatedSectionName = item.ProjectDoc_RelatedSectionName;
                aa.IsActive = item.IsActive;
                aa.IsDraft = item.IsDraft;

                if (item.IsDraft == 1)
                {
                    var_Alldocclosed = true;
                }
                if (item.IsDraft == 5)
                {
                    var_Anydocopen = true;
                }
                if (item.IsDraft == 6)
                {
                    var_Anydocpermanent = true;
                }
            }

            if (var_Anydocpermanent)
            {
                aa.IsDraftAllDocuments = 6;
            }
            else if (var_Anydocopen)
