        //Public-Unpublic Handler (Project Document By Index)
        public JsonResult PublicUnpublicHandler_ProjectDocumentByIndex(string prmprojectId, string prmprojectdocindexId, string prmprojectdocId, string prmPublicUnpublic)
        {
            Int32 retvaluePublicUnpublic = 0;
            Int32 retValue = 1;
            try
            {
                #region Parameters
                Int64 ProjectCode = 0;
                Int64 ProjectDocIndexCode = 0;
                Int32 ProjectDocCode = 0;
                string PublicUnpublicCode = "YPV";
                string userName = string.Empty;
                string userID = string.Empty;
                string RelatedRemarksIfAny = string.Empty;
                string RelatedPVMsg = string.Empty;

                if (prmprojectId != string.Empty)
                {
                    ProjectCode = Convert.ToInt64(prmprojectId);
                }
                if (prmprojectdocindexId != string.Empty)
                {
                    ProjectDocIndexCode = Convert.ToInt32(prmprojectdocindexId);
                }
                if (prmprojectdocId != string.Empty)
                {
                    ProjectDocCode = Convert.ToInt32(prmprojectdocId);
                }
                if (prmPublicUnpublic != string.Empty)
                {
                    if (prmPublicUnpublic == "true")
                    {
                        // has class YPV, request for UnPublicView. hence set NPV
                        PublicUnpublicCode = Convert.ToString("NPV");
                    }
                    else if (prmPublicUnpublic == "false")
                    {
                        // has class NPV, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                    else
                    {
                        // has class unknown, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project document details";
                switch (PublicUnpublicCode)
                {
                    case "NPV":
                        RelatedPVMsg = "UnPublicView request";
                        break;
                    case "YPV":
                        RelatedPVMsg = "PublicView request";
                        break;
                    default:
                        RelatedPVMsg = "others (PublicView)";
                        break;
                }
                #endregion
                ClsMethod_View_ProjectDocuments sdb = new ClsMethod_View_ProjectDocuments();
                retvaluePublicUnpublic = sdb.Update_PublicUnpublicHandler_Project_DocumentDetailsByIndex(ProjectCode, ProjectDocIndexCode, ProjectDocCode, PublicUnpublicCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
            }
            catch (Exception ex)
            {
                string retex = ex.ToString();
                retValue = 0;
            }

            Int32 IsFlag = retvaluePublicUnpublic; // 5;            
            Int32 parmStatusCode = 102;
            string parmStatus = "Request processed! Invalid.";
            if (retValue == 1)
            {
                if (IsFlag == 101)
                {
                    parmStatusCode = 101;
                    parmStatus = "Enabled successfully public view of project documents.";
                }
                else if (IsFlag == 105)
                {
                    parmStatusCode = 105;
                    parmStatus = "Disabled successfully public view of project documents.";
                }
                else if (IsFlag == 106)
                {
                    parmStatusCode = 106;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }                
                else
                {
                    parmStatusCode = 100;
                    parmStatus = "Invalid Enabled-Disabled Action.";
                }
            }
            else
            {
                parmStatusCode = 102;
                parmStatus = "Request processed! Failed.";
            }

            return Json(new
            {
                statusCode = parmStatusCode,
                status = parmStatus,
                remarks = string.Empty
            }, JsonRequestBehavior.AllowGet);
        }
