                Int32? strstatecode = Convert.ToInt32(objprp.Prpparententity[h].State);
                objprp.Prpparententity[h].State = objdis.State_Name(strstatecode);
            }

            objprp.prpMem = objDB.Display_MemProject(Application_id);            
            for (var i = 0; i < objprp.prpMem.Count; i++)
            {
                Int32? strDistrictCode = Convert.ToInt32(objprp.prpMem[i].District);
                objprp.prpMem[i].District = objdis.District_Name(strDistrictCode);

                Int32? strstatecode = Convert.ToInt32(objprp.prpMem[i].State);
                objprp.prpMem[i].State = objdis.State_Name(strstatecode);
            }


            objprp.promoterDoc = sdbdocsidelist.Display_AuthDesk_Promoter_Documents_PromoterId(Application_id);
            
            //lock-unlock method - start
            if (objprp != null)
            {
                objprp.IsDraftpromoterprofile = objprp.IsDraft;                
            }            
            if (objprp.Prpparententity != null)
            {
                foreach (var item in objprp.Prpparententity)
