        [HttpGet]
        public ActionResult Display_ProjectUpdatesCIIEFPDetails()
        {
            ClsMethod_View_Project_Updates_CIIEFP sdb = new ClsMethod_View_Project_Updates_CIIEFP();
            ClsPrp_AuthDesk_View_ProjectBuildingTowerBlock_Construction aa = new ClsPrp_AuthDesk_View_ProjectBuildingTowerBlock_Construction();

            ClsMethod_View_ProjectDocuments sdbpdoclist = new ClsMethod_View_ProjectDocuments();

            string userRole = string.Empty;
            Int64 ProjectID = 0;
            userRole = getUserRole();
            if (Session["zipProjectDiaryNumber"] != null)
            {
                Int64? Project_ID = Convert.ToInt64(Session["zipProjectID"]);
                ProjectID = (Project_ID != null) ? Convert.ToInt64(Project_ID) : 0;
            }

            aa.prpongoing = sdb.Display_AuthDesk_ProjectBuildingTowerBlock_Construction(ProjectID, 0, "");
            aa.PrpInventory = sdb.Display_AuthDesk_ProjectBuildingTowerBlock_Inventory(ProjectID, 0, "");
            aa.PrpInternalFacility = sdb.Display_AuthDesk_ProjectInternalInfrastructure_Facilities(ProjectID, 0, "");
            aa.PrpExternalFacility = sdb.Display_AuthDesk_ProjectExternalInfrastructure_Facilities(ProjectID, 0, "");
            aa.PrpParking = sdb.Display_AuthDesk_ProjectParkingDetails(ProjectID, 0, "");
            aa.ProjectDocumentsList = sdbpdoclist.Display_Project_Documents_ByProjectId(ProjectID);

            foreach (var item in aa.prpongoing)
            {
                aa.IsDraftListConstruction = item.IsDraft;
            }

            foreach (var item in aa.PrpInventory)
            {
                aa.IsDraftListInventory = item.IsDraft;
            }

            foreach (var item in aa.PrpInternalFacility)
            {
                aa.IsDraftListInternalfac = item.IsDraft;
            }

            foreach (var item in aa.PrpExternalFacility)
            {
                aa.IsDraftListExternalfac = item.IsDraft;
            }

            foreach (var item in aa.PrpParking)
            {
                aa.IsDraftListParking = item.IsDraft;
            }


            if (Session["zipProjectDiaryNumber"] != null)
            {
                string ProjectDiaryNumber = Session["zipProjectDiaryNumber"].ToString();
                string ProjectName = Session["zipProjectName"].ToString();
                Int64? Project_ID = Convert.ToInt64(Session["zipProjectID"]);
                DateTime? LastModifiedOn = Convert.ToDateTime(Session["zipLastModifiedOn"]);
                Int64? PromoterID = Convert.ToInt64(Session["zipPromoterID"]);

                aa.zipRelated_Promoter_ID = (PromoterID != null) ? Convert.ToInt64(PromoterID) : 0;
                aa.zipRelated_Project_ID = (Project_ID != null) ? Convert.ToInt64(Project_ID) : 0;
                aa.zipProject_DiaryNumber = (String.IsNullOrEmpty(ProjectDiaryNumber) ? "" : ProjectDiaryNumber);
                aa.zipProjectName = (String.IsNullOrEmpty(ProjectName) ? "" : ProjectName);
                aa.zipProjectLastModifiedOn = LastModifiedOn;
            }

            TempData["CurrentYears"] = null;
            ViewBag.Years = GetYears();

            return View("Display_ProjectUpdatesCIIEFPDetails", aa);
        }

        private static List<SelectListItem> GetYears()
        {
            List<SelectListItem> Years = new List<SelectListItem>();

            for (Int32 i = (DateTime.Now.Year); i <= (2050); i++)
            //for (Int32 i = (DateTime.Now.Year); i <= (DateTime.Now.Year + 25) ; i++)
            //for (Int32 i = (DateTime.Now.Year); i <= (DateTime.Now.Year); i++)
            {
                Years.Add(new SelectListItem
                {
                    Text = Convert.ToString(i),
                    Value = Convert.ToString(i)
                });
            }

            return Years.ToList();
        }

