        [HttpGet]
        public ActionResult Display_ProjectPhotographDetails()
        {
            ClsMethod_View_Project_Updates_ConstructionStatusPhotographs sdb = new ClsMethod_View_Project_Updates_ConstructionStatusPhotographs();
            ClsPrp_AuthDesk_View_ProjectConstructionStatusPhotographs aa = new ClsPrp_AuthDesk_View_ProjectConstructionStatusPhotographs();

            ClsMethod_View_ProjectDocuments sdbpdoclist = new ClsMethod_View_ProjectDocuments();

            string userRole = string.Empty;
            Int64 ProjectID = 0;
            userRole = getUserRole();
            if (Session["zipProjectDiaryNumber"] != null)
            {
                Int64? Project_ID = Convert.ToInt64(Session["zipProjectID"]);
                ProjectID = (Project_ID != null) ? Convert.ToInt64(Project_ID) : 0;
            }

            aa.prpongoing = sdb.Display_AuthDesk_Project_ConstructionStatusPhotographs(ProjectID, 0, "");
            aa.ProjectDocumentsList = sdbpdoclist.Display_Project_Documents_ByProjectId(ProjectID);

            #region Lock - Unlock (Logic Display Message)
            bool var_Anydocopen = false;
            bool var_Alldocclosed = false;
            bool var_Anydocpermanent = false;

            if (aa.prpongoing.Count == 0)
            {
                aa.IsDraftListAdvtPhotograph = 0;
            }

            foreach (var item in aa.prpongoing)
            {
                aa.ProjectPhotographs_IndexID = item.ProjectPhotographs_IndexID;
                aa.ProjectPhotographs_ID = item.ProjectPhotographs_ID;
                aa.ProjectPhotographsRelated_Project_ID = item.ProjectPhotographsRelated_Project_ID;
                aa.Promoter_ID = item.Promoter_ID;
                aa.TypeRelated_BuildingTowerBlock_ComArea_AdvtProspectus_Code = item.TypeRelated_BuildingTowerBlock_ComArea_AdvtProspectus_Code;
                aa.TypeRelated_BuildingTowerBlock_ComArea_AdvtProspectus_Name = item.TypeRelated_BuildingTowerBlock_ComArea_AdvtProspectus_Name;
                aa.IsActive = item.IsActive;
                aa.IsDraft = item.IsDraft;

                if (item.IsDraft == 1)
                {
                    var_Alldocclosed = true;
                }
                if (item.IsDraft == 5)
                {
                    var_Anydocopen = true;
                }
                if (item.IsDraft == 6)
                {
                    var_Anydocpermanent = true;
                }
            }

            if (var_Anydocpermanent)
            {
                aa.IsDraftListAdvtPhotograph = 6;
            }
            else if (var_Anydocopen)
            {
                aa.IsDraftListAdvtPhotograph = 5;
            }
            else if (var_Alldocclosed)
            {
                aa.IsDraftListAdvtPhotograph = 1;
            }
            else
            {
                aa.IsDraftListAdvtPhotograph = 0;
            }
            #endregion

            if (Session["zipProjectDiaryNumber"] != null)
            {
                string ProjectDiaryNumber = Session["zipProjectDiaryNumber"].ToString();
                string ProjectName = Session["zipProjectName"].ToString();
                Int64? Project_ID = Convert.ToInt64(Session["zipProjectID"]);
                DateTime? LastModifiedOn = Convert.ToDateTime(Session["zipLastModifiedOn"]);
                Int64? PromoterID = Convert.ToInt64(Session["zipPromoterID"]);

                aa.zipRelated_Promoter_ID = (PromoterID != null) ? Convert.ToInt64(PromoterID) : 0;
                aa.zipRelated_Project_ID = (Project_ID != null) ? Convert.ToInt64(Project_ID) : 0;
                aa.zipProject_DiaryNumber = (String.IsNullOrEmpty(ProjectDiaryNumber) ? "" : ProjectDiaryNumber);
                aa.zipProjectName = (String.IsNullOrEmpty(ProjectName) ? "" : ProjectName);
                aa.zipProjectLastModifiedOn = LastModifiedOn;
            }

            TempData["CurrentYears"] = null;
            ViewBag.Years = GetYears();

            return View("Display_ProjectPhotographDetails", aa);
        }

