                    }
                    else if (prmPublicUnpublic == "false")
                    {
                        // has class NPV, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                    else
                    {
                        // has class unknown, request for PublicView. hence set YPV
                        PublicUnpublicCode = Convert.ToString("YPV");
                    }
                }
                userID = User.Identity.GetUserId();
                userName = User.Identity.GetUserName();
                RelatedRemarksIfAny = "Project status of contruction with photographs details";
                switch (PublicUnpublicCode)
                {
                    case "NPV":
                        RelatedPVMsg = "UnPublicView request";
                        break;
                    case "YPV":
                        RelatedPVMsg = "PublicView request";
                        break;
                    default:
                        RelatedPVMsg = "others (PublicView)";
                        break;
                }
                #endregion
                ClsMethod_View_QuarterlyUpdatesProjectStatusConstructionPhotographs sdb = new ClsMethod_View_QuarterlyUpdatesProjectStatusConstructionPhotographs();
                retvaluePublicUnpublic = sdb.Update_PublicUnpublicHandler_QuarterlyUpdatesProject_StatusConstructionPhotographsByIndex(ProjectCode, ProjectPhotographsIndexCode, ProjectPhotographsCode, PublicUnpublicCode, userName, userID, RelatedRemarksIfAny, RelatedPVMsg);
