        private string funConvertQuarterIdToQuarterText(Int32 varInput)
        {
            string varReturn = string.Empty;
            switch(varInput)
            {
                case 1:                    
                        varReturn = "FirstQTR";
                        break;                    
                case 2:                    
                        varReturn = "SecondQTR";
                        break;                    
                case 3:                    
                        varReturn = "ThirdQTR";
                        break;                    
                case 4:                    
                        varReturn = "FourthQTR";
                        break;                    
                default:                    
                        varReturn = "FirstQTR";
                        break;                    
            };
            return varReturn;
        }
